"""Changelog data + its modal renderer (carved out of _core.py in Phase 3)."""
import html
E = html.escape


_CHANGELOG = [
    ("0.99.65", ["ARMADA now has a Windows installer. It installs for you alone, with no administrator rights, and brings its own copy of Python, so there's nothing else to set up. It adds ARMADA to the Start menu (and the desktop, if you like) and can start the scheduler when you sign in to Windows, so your jobs carry on after a restart without opening the window. Uninstalling removes the program and leaves your realms and settings exactly where they were.", "ARMADA's window needs Microsoft Edge WebView2, which nearly every Windows 10 and 11 computer already has. If it's missing, the installer installs it from Microsoft (asking first if Windows needs your permission). And the app no longer opens a broken, unstyled window without it: it says what's missing and where to get it.", "The installer also tells you at the end if Claude Code isn't installed yet, with a link to Anthropic's install guide."]),
    ("0.99.64", ["ARMADA can now keep itself up to date once it's installed. Twice a day it checks for a new version; one that's found is downloaded and checked against ARMADA's release signature before anything else happens, so a download that's been tampered with, or an old version passed off as new, is never installed. The new version goes in the next time ARMADA starts, or straight away when the window is closed and nothing is running. While the window is open, a bar under the menu says a new version is ready and offers Restart to update. Your realms and settings are never touched.", 'Settings → App → Advanced has the switch for this (on by default). Off means nothing is checked or downloaded until you press Check for updates. The Jobs page lists it as “Keep ARMADA up to date”, with the same switch.', 'A version that changes more than the app itself (the Python it runs on, say) comes as a new installer instead; the bar says so and links to it.']),
    ("0.99.63", ["The coordinator's mark is now a laurel wreath.", "An agent's own memories: the head-and-snowflake icon is a little larger and sits level with the card's heading."]),
    ("0.99.62", ["New, for trying out: Settings → App → Appearance → Fonts. Pick the face for headings and for body text from six families (Barlow, Barlow Condensed, Montserrat, Nunito Sans, Quicksand, Roboto). Each is resized to take the same room as the design's own fonts and sits on the same baseline, so switching doesn't push text out of buttons or break rows. This is a trial ahead of proper themes.", "The coordinator now wears a medal instead of a laurel, and an agent's own memories are marked with a head-and-snowflake icon.", 'Smaller logo in the menu bar; in Settings → App the ARMADA lockup is smaller and the version stands on its own. The Windows taskbar/window icon now fills its square. The icon on "Make existing jobs portable" is larger.']),
    ("0.99.61", ['Fixed occasional lost saves on Windows. When another program (another part of ARMADA, an antivirus scanner, the search indexer) was reading a file at the exact moment ARMADA saved it, Windows refused the save with "file in use". It showed up in the Telegram listener\'s state first; any save could hit it. ARMADA now waits a moment and tries again.']),
    ("0.99.60", ["New: Report an issue. The icon beside the settings gear, on every page, opens a short form: say what happened, add your email if you'd like a reply, and choose whether to include the last lines of ARMADA's logs. You then see the whole report exactly as it will be sent — keys, tokens, email addresses and your Windows user name are taken out of the logs first — and nothing leaves until you press Send. If it can't be sent, it's saved on your computer and ARMADA tells you where."]),
    ("0.99.59", ['Fixed Restart sometimes not coming back. Restarting ARMADA closes its connection and starts a fresh copy; occasionally the old copy finished closing before the new one had started, and the app simply disappeared. The old copy now waits for the new one.']),
    ("0.99.58", ["Security: pages ARMADA didn't write now run apart from the app. A section's own mini-site, a mirrored copy of a web page, or an HTML file an agent attached could run scripts with the same access as the app itself — enough to start an agent turn. They're now served from a separate local address the app doesn't trust, so their scripts can't reach it. Mini-sites keep working as before, including remembering their own settings.", "Security: other web pages can no longer make the app do things through a plain link or image — a request that doesn't come from the ARMADA window is refused."]),
    ("0.99.57", ['Security: reviewing a link is now sealed off. The agent that reviews a repository or page you paste could previously use every tool — run commands, write files, use your connected services — while reading content written by someone else, and a page can contain instructions aimed at whoever reads it. Now it can only read the web: no commands, no files, none of your connections. The review may occasionally go less deep; it can no longer be turned against you.']),
    ("0.99.56", ['ARMADA\'s insides now use its name too. Until now the code, its command and its folder on your computer were still called "matcap", the app\'s working name, so you could find a .matcap folder in your user folder, "matcap" in Task Manager and matcap.log in the logs. All of it is ARMADA now. Nothing to do on your side: your settings, realm list, logs and sign-ins move from .matcap to .armada the first time ARMADA starts.', 'Existing realms are updated the first time they\'re opened: a scheduled command that ran ARMADA\'s own tools under the old name now uses the new one, so it keeps working instead of failing with "No module named matcap".']),
    ("0.99.55", ['Internal only — getting the source ready to publish: a new README, the old development log moved under docs/dev, a personal migration script and an unlicensed font removed from the repository, and example text that described the developer replaced with neutral examples.']),
    ("0.99.54", ['System jobs (the model list refresh and the rest of ARMADA\'s own upkeep) now record when they ran through the same clock everything else reads. Internal in effect — the times shown don\'t change — but it closes a gap where a job\'s "next run" could be computed from two different notions of now.', 'Internal only — the last two page snapshots the test suite had stopped checking are back in service.']),
    ("0.99.53", ["Choosing a folder (for a new realm, or ARMADA's own folder) now opens the standard Windows folder picker, attached to the ARMADA window, so it can't open hidden behind it."]),
    ("0.99.52", ['Internal only — nothing in the app looks or behaves differently. If ARMADA ever fails to start, or fails to come back after Restart, the reason is now written to the log (matcap.log) instead of vanishing: without a console window, those failures used to leave no trace.']),
    ("0.99.51", ["ARMADA's licence changed from MIT to the PolyForm Noncommercial License: free for personal and other noncommercial use, commercial use by agreement. Settings → App → About says so and links the terms, and the credits for the software, fonts and icons ARMADA is built with now come with it (THIRD_PARTY_NOTICES.md).", 'Internal only — an unused font file was removed from the app.']),
    ("0.99.50", ["ARMADA now says it's a beta — in the window title, beside the logo on every page, and next to the version in Settings → App. It's early software; if something looks wrong, it probably is, and we want to hear about it."]),
    ("0.99.49", ["Opening ARMADA for the first time now opens ARMADA. With no realm yet, the app used to exit without a word — double-click the icon and nothing happened. Now it opens on a welcome page: choose the one folder ARMADA keeps everything in, name your first realm and pick a template, and you're in. Or open a realm you already have.", 'If the realm ARMADA last had open has been moved or deleted, it now says so and lets you open another, instead of not starting.', 'Creating your first realm starts the scheduler, so its jobs run from the start.']),
    ("0.99.48", ["Scheduled jobs no longer stop silently. They're run by a separate background process so they keep going with the window closed — but if that process wasn't running (after a restart, say), nothing ran and nothing told you. Now opening ARMADA starts it if it isn't running, and if it ever stops while a realm has scheduled jobs, a yellow bar under the menu says so on every page, with a Start it button.", "A realm you create or add while the scheduler is running now gets its jobs run straight away. Before, the scheduler only knew the realms that existed when it started, so a new realm's jobs waited until it was restarted.", 'Internal only — the buttons, pills, fields and headings the design-system document describes now exist as shared styles, ready for pages to move onto them. Nothing looks different yet.']),
    ("0.99.47", ['Help is here. The Documentation page was a list of placeholders; it now holds real help — getting started, how ARMADA thinks (realms, agents, memory, goals, jobs, capabilities), a page for each part of the app, staying safe, and what to do when something goes wrong. Links between pages stay in the app, and the search box looks inside every page, not just the titles. Behind the scenes the developer documentation was reorganised the same way, and a test now fails if any help page points at something the app no longer has.']),
    ("0.99.46", ['Adding a realm that already exists — one someone else made, or yours from another computer — now pauses its scheduled jobs until you’ve looked at them. A realm carries command jobs (commands that run on this computer, as you) and agent jobs; until now they started on their own at the next scheduled time. The Jobs page shows a banner with every command written out in full and a button to let them run. Any other reason the scheduler is paused (no workspace, not signed in) now shows there too, instead of only in Settings.', 'Opening or deleting a file from an artefact list now only works inside the realm, its workspace, or the ARMADA folder. The Telegram bot now links and answers only a one-to-one chat, never a group — in a group, everyone in it could have driven your agents. Exporting a realm leaves out files that hold keys or passwords (.mcp.json, .env, key files) and tells you which.', 'Fixed places where a realm name, a thread title or an agent colour could inject markup into the page (the realm switcher, the delete-thread dialog, the Usage widget). All from the security threat model written for the beta.']),
    ("0.99.45", ['Fixed a way to lose edits. Saving an agent’s settings could silently undo a capability you’d just granted it, if the two landed at the same moment — both write the agent’s file, and only one of them waited for the other. The same was true, in smaller ways, of the thread list (renames, pins, the order, which thread you had open, unread marks) and the dashboard layout. All of them now take turns. Nothing looks different; tests check each one.']),
    ("0.99.44", ['Security fix: names shown on buttons and menus can no longer be turned into code. About forty clickable elements passed a name — a capability’s, a thread title, a job name, a filter label — into the page’s script with escaping that the browser undoes before the script runs, so a name containing a quote mark could run its own code inside ARMADA. Capability names come from third-party marketplaces and thread titles are written by a model, so that wasn’t hypothetical. Every such spot now uses escaping that holds, and a test fails if the old pattern comes back. The skill viewer’s title had the same problem and is fixed too. Found writing the security threat model; nothing looks or works differently.']),
    ("0.99.43", ['Security fix: ARMADA now refuses any request that doesn’t address it by a local name (127.0.0.1 or localhost). Until now a web page you happened to visit while ARMADA was running could, with a technique called DNS rebinding, make your browser treat it as ARMADA itself — read what the app shows and send it commands, including starting an agent turn. The existing cross-site check compared the request’s origin with the name it was addressed to, and in that attack both are the attacker’s. There’s no sign it was ever used; it was found writing the security threat model for the beta. Nothing changes for you — the app window, and http://127.0.0.1:8756 or http://localhost:8756 in a browser, work as before.']),
    ("0.99.42", ['Dark mode, second pass: the Register, Usage, Job calendar and thread widgets had a light grey title bar in dark mode (with light text on it), and the Usage widget’s empty bar tracks were pale strips. Both now use dark-mode colours; the grey shades they used had never been given dark values. The thread compaction gauge’s track was white in both modes and now matches the page. A test now fails if the interface uses a shade that has no dark-mode value, or a near-white surface colour written straight into the stylesheet.']),
    ("0.99.41", ['Fixed dark mode’s faded text. Muted labels, captions, pills, hover backgrounds and most secondary text were drawn in the light theme’s near-black ink at partial strength — so on the dark background they all but disappeared. The shared shades they use were being worked out once, for the light theme, and never again when the page switched to dark; they now follow the colour mode like everything else. It had always affected a handful of places; v0.99.37’s tidy-up moved about 190 more onto those same shades, which is what made it obvious. A test now fails if any shade is defined in a way that can’t follow the colour mode.']),
    ("0.99.40", ['Internal only — nothing in the app looks or behaves differently. The groundwork for changing ARMADA without changing its code: add-ons. An add-on is a folder with one addon.json — data, never code — that can offer dashboard widgets (static markdown or a list of links), saved filters for the Jobs list and the Capabilities page, colour themes, pre-filled agent-job templates, and dashboard layouts. They live in the realm’s own addons folder (so they travel with it) or in this install’s, and removing one is deleting its folder. Every piece is checked against a fixed shape before anything could use it; a broken add-on is skipped with a plain reason rather than breaking anything, and templates can never carry a shell command. Nothing uses them yet — this is the surface Alexander will write into later, instead of editing the app. Called add-ons rather than plugins because “plugins” already means Claude Code plugins on the Capabilities page. The contract is docs/EXTENSION_POINTS.md. Phase 2, 2.7.']),
    ("0.99.39", ['Internal only — nothing in the app looks or behaves differently, but when something quietly falls back, the reason is now written down. ARMADA catches errors broadly in about 280 places on purpose (a badge must not break a page, a telemetry write must not fail a job, one unreadable agent.json must not blank the roster), and 267 of those threw the reason away. Each now logs before doing exactly what it did before: most through one shared helper that writes the traceback to ~/.matcap/logs, treats a missing file as the ordinary “nothing there yet” case rather than an error, and holds back repeats of the same failure for five minutes so one corrupt file on a page that renders every few seconds can’t flush the log of everything else; 71 where the failure is the expected path (a probe, a browser that has closed mid-stream, a date that doesn’t parse) log at debug level only. The scheduler — a separate, windowless process — now keeps its own log, scheduler.log, beside the app’s; until now anything it logged went nowhere. A test scans the code so a new silent catch-all fails the suite. Phase 2, 2.5.']),
    ("0.99.38", ['Realms now carry a format version. realm.json gains an integer schema_version, and a realm is brought up to the current format whenever ARMADA opens it (starting the app, switching realms, the scheduler’s pass over every registered realm) or adopts it from another folder. The first migration changes nothing but the stamp — its job is to make every realm on disk say which format it’s in before the first change that isn’t simply additive (a renamed key, a split file) needs to tell an old realm from a new one; until now every field added this month relied on readers defaulting a missing key, which can’t distinguish “written before” from “left blank”. Realms stamped “0.1” by older builds of `matcap new` count as the unversioned starting point. A realm saved by a NEWER ARMADA is never migrated backwards: it’s left exactly as it is, adopting one shows a warning, and `matcap validate` flags it. A migration that fails is logged and the realm still opens. The rules for the next real migration are written down in docs/SCHEMA.md. Phase 2, 2.8.']),
    ("0.99.37", ["Phase 2, 2.2: the 211 inline color-mix() expressions and the modal overlay/box chrome duplicated across the codebase are now shared CSS — the two pieces of “buttons and modals look different page to page when one copy drifts from another” that 2.1 set up but didn’t touch. 190 of the 211 color-mix(in srgb,var(--color-X) NN%,transparent) calls (90%) recurred two or more times and are now a custom property — the existing --text-strong/dim/muted/soft/faint/ghost alpha scale in brand.css extended with the rest of the percentages that recurred (--text-6 through --text-65) plus the same idea for --accent-13/--accent-38/--accent2-7/--status-ok-16/--status-warn-16. The remaining 21 are either one-off percentages or mix against something other than transparent (var(--color-bg), a dynamic Python value) and stayed inline — not the pattern this was after. Caught one real instance of the bug class along the way: static/js/settings.js had its own hardcoded copy of a color-mix string that has to byte-match the Python-rendered one for the realm-icon-picker's “current” ring to line up, and it had drifted from the token rename until fixed — the ~30 other color-mix( calls living in .js files are a separate, larger cleanup and out of scope here. Second piece: the modal overlay/box chrome (display:none;position:fixed;inset:0;… plus a background/radius/padding/shadow box) was duplicated near-verbatim across roughly 20 modals in 9 files; it's now two classes, .mc-modal-ov (or -ov-top for the few that anchor to the top instead of centering) and .mc-modal-box, with only the genuinely per-modal bits — z-index, background alpha, box width, padding when it wasn't the default 18px — left as inline overrides. Three modals (the Covenant modal, the dashboard widget picker, the appoint-agent overlay) use a different alpha, border, or box structure entirely and were left inline rather than force-fit. Pure moves, no behaviour change, guarded by the golden suite (18 pages regenerated, each diff reviewed — including a couple of pages showing a settings.html changelog staleness bug from 2.1's own regold running before that release's version bump, now incidentally corrected). jobs and agent_threads remain excluded for the same pre-existing, unrelated drift noted in 2.1."]),
    ("0.99.36", ['Internal only — nothing in the app looks or behaves differently. Phase 2, 2.1: the 27 remaining inline <script> blocks embedded in Python strings are now externalized to webui/static/js/, the same pattern already used for ~35 other scripts. The motivating bug: a script calling a function a later string defined — order was implicit in how Python string literals happened to concatenate, invisible at a glance and easy to get wrong. Script order is explicit now (each page loads its <script src> tags in the order they matter), and every extracted file is plain, lintable JavaScript (node --check clean across all 28). A handful of blocks had realm-specific data baked into otherwise-static logic; those became parameterized functions in the static file with a tiny per-render <script>call(args)</script> shim left inline, or, for the Covenant modal, switched from a server-baked JSON literal to reading its own already-rendered text off the DOM once on load. A pure move, no behaviour change, guarded by the golden suite (17 pages regenerated, each diff reviewed to confirm only the script tag changed). Two golden pages (jobs, agent_threads) were already drifting on master for an unrelated reason before this change and are left as they were.']),
    ("0.99.35", ["Fixed the branding assets landed in v0.99.34: the source SVGs had a stray white stroke/halo around two of the titlebar mark's bars, visible as a faint white border in the header and Settings wordmark. Re-exported from the corrected files—titlebar mark, Settings wordmark, and the app's OS window/taskbar icon, which still carried an older logo (a fist-and-circuit emblem, predating even the ARM/ADA placeholder) and now shows the new symbol at every size Windows asks for (16 through 256px)."]),
    ("0.99.34", ['New Armada branding. The titlebar mark is now the new symbol—three angled bars forming a stylised “A”, teal and navy with a white cut-out—replacing the old ARM/ADA text placeholder, exported at the same 30px height it always rendered at. The App settings page’s Version section now leads with the full lockup (mark + wordmark) above the version number and buttons, using the new standard mark.']),
    ("0.99.33", ["Internal only — nothing in the app looks or behaves differently. Two pieces, folded together since both touch the same file’s locking. First, the other half of 0.99.32’s split: catalogue.py (1,578 lines, both the data-layer fetch/search side and the realm-writing side in one file) is now a package, matcap/catalogue/ — _shared.py (277 lines: constants and the name/id matching both other files build on), sources.py (600 lines: the three mirrored/queried sources — marketplaces, the MCP registry, skills), and realm.py (727 lines: adding a capability to a realm, adopting what discovery found, fetching a skill, the bring-a-link review flow). __init__.py re-exports every public and private name the single file used to expose, so every external caller (webui, routes, sysjobs, capscan) is unchanged. The real risk in a split like this: 13 private names were monkeypatched offline in tests across 9 files and roughly 60 call sites — a test patching the package’s re-export no longer reaches a name a submodule imported into its own namespace, so the patch silently stops working. All were found and repointed at the module that actually resolves each name, including the same trap in the suite’s own global fixture (conftest.py), which is what most of the failures traced back to.",
                 "Second, 2.9’s own scope: a concurrency pass on the scheduler ↔ server boundary. Auditing every realm.json write turned up five capability-editing routes (save, toggle, delete, permission, refresh connectors) and six dashboard section-editor routes (add, rename, delete, reorder, and the two widget/section adders) doing an unlocked read-modify-write — a save from the UI landing between the scheduler’s own read and write could silently lose one side’s edit. All eleven, plus workspace.py’s migrate() and set_root(), now wrap their read-modify-write in the same file lock capscan.scan() and catalogue.add_to_realm() already used. Separately: two schedulers ticking the same realm — a daemon left running in a forgotten terminal plus a second one started later, or a persistent daemon plus a one-shot --once run in the same minute — could double-fire a job, since the existing run-report check only closes that race after a job finishes, not while it’s in flight. Each realm now gets its own scheduler.lock.json naming the pid currently ticking it: run_daemon() refuses to start a second time over a realm another live process already owns (and drops only the --also realms someone else owns, rather than refusing outright), and a standalone tick() call backs off rather than racing an already-running daemon. A lock naming a pid that’s no longer running is recognised as stale, from a crash, and taken over rather than left stuck. Full suite clean against the standing 32-failure baseline, 25 new tests covering the lock behaviour directly."]),
    ("0.99.32", ["Internal only — nothing in the app looks or behaves differently. webui/capabilities.py had grown to over 2,000 lines carrying both the User/System tabs’ rendering and the Catalogue tab’s (search results, the bring-a-link review report, the info box) in one file — every round of Catalogue work this month meant reading the whole thing. The Catalogue tab’s rendering (14 functions: _cat_results, _cat_card, _catalogue_pane, _cat_review_card and the rest) now lives in a new webui/catalogue.py, 842 lines. capabilities.py, now 1,263 lines, keeps the User tab, the System tab, and the cross-cutting trust-model helpers both tabs’ cards are built from (risk tier, Runs/Can-touch icons, kind labels) — catalogue.py imports the three of those it needs. _realm_skills, the page that stitches all three tabs into one screen, stays in capabilities.py and reaches into catalogue.py locally for the two pieces it needs (_catalogue_pane, its filter JS), the same way it already reached into the data-layer catalogue.py for realm lookups — avoiding a module-level import cycle between the two new files. Second half of the pair the plan called out to do first, before either file gets touched again. Full suite clean, zero golden-page diffs, and smoke-tested against a live server end to end."]),
    ("0.99.31", ["Bring a link now checks across every realm before Add is even offered, not just this one. Reviewing a link for a capability already added — anywhere — shows a small line under the assessment: “Already added to this realm” (with Add turned off) or “Added to Cabinet2, Skunkworks” (Add stays on — every realm still adds for itself). The underlying bug: the same-realm duplicate check compared a plain lowercase id against one that had already had its punctuation stripped, so a capability recorded as “frontend-design” and a fresh review of the same source calling itself “Frontend design” never matched — which is exactly how a link for a capability already in the realm slipped through and landed twice. Both checks now use the same name-token matching the catalogue’s own “already added” hint has always used, across every kind bucket in the realm, not just the one the new entry would land in."]),
    ("0.99.30", ["Internal only — nothing in the app looks or behaves differently. serve.py had grown to over 3,000 lines carrying every HTTP handler in one file; its 158 handler methods are now split across 8 files under matcap/routes/, grouped by area (realm, agents, jobs, capabilities, catalogue, settings, dashboard, plus a shared module for cross-cutting helpers), mixed back into the same Handler class. The route tables and core dispatch stay in serve.py, now 574 lines. Full suite clean, zero golden-page diffs, and smoke-tested against a live server end to end. First step of Phase 2 (architecture review and refactoring) — the plan’s own docs/LAUNCH_PLAN.md called this one out to do first, since it cuts the context every later step needs to read."]),
    ("0.99.29", ["The assessment icon on the bring-a-link report card was smaller than the warning icon in its own Flagged section right below it — same card, two sizes. Both are 18px now."]),
    ("0.99.28", ["Bring a link, round three. The report was showing two risk-sounding pills at once — “Medium risk” and “medium confidence” — and a capability that can run shell commands could still land “Medium” if that was the reviewing agent’s own word for it, even though the User tab would flag the same ability red. The confidence pill is gone; the risk pill is now floored to at least the mechanical worst-case every other capability in the app is held to (Runs/Can touch alone), so a shell-reaching capability can’t read softer here than it would anywhere else — the agent’s own verdict can only raise the bucket, never lower it.",
                 "The Runs/Can touch icons moved into the header row, where the confidence pill used to sit, next to “by X” — the same inline cluster the User tab uses, not a separate band underneath any more. A new icon leads the risk pill, and “Armada’s recommendation” is now “Armada’s assessment”. A flagged finding now shows a bolder, larger warning glyph than the plain outline triangle used elsewhere.",
                 "Fixed a paragraph-break bug in the full evidence report: a compound label the agent wrote as its own phrase, “DECLARED vs OBSERVED — …”, was being read as two separate section labels and split apart mid-phrase, which looked like broken markup. The break now only lands before an actual section label.",
                 "The “Full review” toggle uses the same animated caret a capability card’s own expand arrow uses, instead of a static chevron."]),
    ("0.99.27", ["Bring a link, round two of the same day’s feedback. The Review button and the status line below it were both saying “still working” the same way — dots and a clock on the button, dots and a clock in the text — so one of each was dropped from each: the button now just counts (“Reviewing… 0:42”), the status line just spins.",
                 "The search spinner moved off the search box and into the results themselves: filtering or searching now clears the list and shows only the dots until the answer is back, rather than dimming a list that’s about to be replaced anyway.",
                 "The recommendation now leads with one of three risk buckets — High / Medium / Low, red / amber / green — the reviewing agent’s own conclusion from everything in Step 5, not just a mechanical read of runs and touch. A review that gives one now also sets the capability’s trust tier when it’s added, so the card and the User tab agree; one that doesn’t falls back to the same runs/touch read every other unrated capability gets.",
                 "The full evidence report, expanded, was one dense paragraph even though the agent’s own Step 5 format is section by section (Bucket, Runs, Can touch, Evidence, Confidence, What was not checked). It now breaks into a paragraph per section."]),
    ("0.99.26", ["Bring a link’s review report is easier to read: a short “Armada’s recommendation” now leads the card — what the capability actually does, and any risk found, in a couple of plain sentences — with the full step-by-step evidence report collapsed behind “Full review” rather than printed in full as one dense, small-font paragraph. The card reuses the same Runs / Can touch icons and risk colours the User tab’s cards use, instead of a plain “runs: X · can touch: Y” line of text.",
                 "The Review button now shows it’s actually working: a small dots spinner and a running clock (“Reviewing… 0:42”) for as long as the agent turn takes — genuinely a couple of minutes — rather than a disabled button with static text that read as hung.",
                 "The MCP registry’s Source filter is no longer a dead end with nothing typed. Dropping the empty-search sample (0.99.25) also meant the option greyed itself out before you’d searched for anything, which read as broken rather than as “search instead”. The registry now samples its first ~100 entries even with an empty box, same as the rest of the filters, so the option stays pickable from the moment the tab opens — still with no network call while the page itself is rendering; only once the Catalogue tab is actually opened.",
                 "Filtering and searching the catalogue now show a small spinner in the search box while the request is in flight, alongside the existing dimming — a signal that wasn’t there before."]),
    ("0.99.25", ["The Catalogue is now “Add a capability”, and it no longer pretends you can browse the MCP registry: it holds 33,657 unranked, unattributed servers with no popularity signal, and an empty search used to render a sample of 100 of them under a “Suggested” order this app made up. That’s gone — with nothing typed, the pane shows only the two sources it actually mirrors (the plugin marketplace, Anthropic’s skills), and says the registry is searched rather than browsed. No network call happens until you type.",
                 "Bring a link: paste a repository, package or MCP server URL and an agent runs the same capability-review protocol used elsewhere in the app — reading the real thing, not just its README — and reports what it found: what it is, who publishes it, what it can reach, and anything worth flagging. You read the report before Add is enabled; nothing is installed or run before then. This is the path that reaches everything the two mirrored sources don’t.",
                 "Results are sorted alphabetically. The old “Suggested” order (Anthropic first, then already-in-your-realms, then vendors publishing several) is retired along with the reasoning that justified each card’s position — there’s no default list left to rank now that browsing is gone, and alphabetical doesn’t pretend to know more than the two sources actually say."]),
    ("0.99.24", ["Refresh catalogue and the “updated” note moved down to the right-hand end of the filter row, where there was room for them. They had a line of their own above the info box, for one button and a timestamp; the explainer, the filters and the results now share one set of edges."]),
    ("0.99.23", ["Capabilities opens straight away. Building the Catalogue’s results queries the MCP registry, and that call was sitting on the render path of the whole page — so the click waited for it, about 700ms on a good day and up to the 20-second timeout on a bad one, for a pane that starts hidden behind the User tab. The page now arrives with everything it can know from disk, and the results load when you open the Catalogue tab, behind placeholder cards that hold the layout still.",
                 "The Catalogue’s info box runs the full width of the pane, matching the filter row under it, and is headed like a widget on the Overview — the same class, so the two can’t drift apart. Refresh catalogue moved to its own line above it, which is what was making the box stop short.",
                 "“Claude subscription limits” in the Overview header lines up with the other captions. Its block is the same height as a stat cell but was centring its contents while the stats stack from the top, which left it a few pixels low."]),
    ("0.99.22", ["Searching the Catalogue for a common word no longer claims you already have everything it finds. Searching “filesystem” returned eleven MCP servers, every one ticked “in Cabinet2” with its Add button disabled — including one called chroot-filesystem-jail-mcp — because this realm happens to run a local server called filesystem. A tick against something you don’t have is worse than no tick: this page exists to tell you what you are running.",
                 "Two causes. The “already installed” mark matched names loosely, so any server with that word in it counted; it is an exact match now, and it is skipped entirely for capabilities whose origin is already known. And discovery kept only a server’s NAME, throwing away the command line — which is the one thing that says what it actually is.",
                 "So filesystem and pdf-viewer are no longer of unknown origin: their command lines identify them as Claude Desktop extensions published by Anthropic, and they say so. Nothing had to be removed.",
                 "Where a capability isn’t identified outright, what it RUNS now outranks what it is called. windows-mcp resembles two published servers; the machine runs “uvx windows-mcp” and only one of them declares that package, so the guess became a fact.",
                 "Claude’s own connectors are called things like “claude.ai Google Drive”, and the scanner was dropping every name containing a space — and with it the URL that identifies each one. They are read properly now."]),
    ("0.99.21", ["The pill beside a capability on the User tab says where it came from — “from Anthropic skills”, “from MCP registry”, “from Created by you” — using the same names the Catalogue’s Source filter uses. It used to say who made it, and for most things nobody was named, so it said “by Third-party”: not a publisher, not a place, and not an answer to either question. That label is gone from the app.",
                 "The source it shows is read off the capability’s catalogue key rather than stored separately, so the pill and the Catalogue cannot drift apart. Anything wired up in Claude rather than added from a source says “from Claude” instead of being given a source it never came from.",
                 "The User tab’s Source filter now offers those same sources, built from what is actually on the page — so it can only offer values you can see on a card, and it no longer offers “Third-party (company)”, which appeared on none of them.",
                 "The publisher hasn’t vanished with the old pill: where one is known, the expanded panel has a Published by line. This page is headed “who made it”, and the pill now answers a different question."]),
    ("0.99.20", ["Capabilities that were already in a realm now carry the Catalogue’s name and provenance. A connector Claude set up arrived called claude_ai_Interactive_Brokers_IBKR, published by nobody, filed as “Added & authorised in Claude” — while the Catalogue lists the same server as Interactive Brokers (IBKR), from the MCP registry, with a publisher and a link. Both were true; only one is useful. It runs with the daily catalogue job and when you press Refresh catalogue.",
                 "It only renames on certainty. The match has to be on a name both sides actually share — not a resemblance — and it has to be the only candidate: your `filesystem` extension resembles several published servers called Filesystem, and picking one would credit your own tool to a stranger. `windows-mcp` resembles someone else’s `windows-mcp-server` and matches CursorTouch’s Windows-MCP exactly; it takes the second. Anything you wrote yourself is never touched, the id never changes (grants are keyed by it), and nothing gets switched on.",
                 "“You” is now “Created by you” in the Catalogue’s sources."]),
    ("0.99.19", ["Skills an agent fetched from elsewhere are their own source in the Catalogue, separate from the ones written here. There are three ways a capability reaches a realm — added from the Catalogue, written here, or pulled from a repository link by an agent — and only the first left any trace. The other two both showed up under “You”, so something fetched off the internet was presented as your own work, which is the one claim that decides whether it gets looked at.",
                 "Each card under “Installed by an agent” says where it came from, and the skill doesn’t count as trusted-by-authorship any more — it is exactly as reviewed as wherever it came from, which is usually nobody.",
                 "New system skill, Skill registry, under Capabilities → System. Every agent is given it automatically rather than having to be granted it: a register only works if everyone keeps it, and one agent quietly filing nothing leaves you with a list that looks complete. It asks for one file beside any skill an agent writes or fetches — origin, where from, who and why — which travels with the folder, so a skill copied to another realm carries its history. You can read exactly what your agents were told on its page, and it updates when ARMADA does.",
                 "Skills already on disk with no record are checked against the Catalogue: where one matches something a known source lists — most came over from Claude Desktop — it takes that source’s author and description instead of being credited to you. Only a skill that matches nothing is called authored."]),
    ("0.99.18", ["The Catalogue’s explanation is an info box you can open, not four paragraphs pinned above the results. Closed it is one line; open it covers what the four capability types are, where each source comes from and what happens when you add something. The type descriptions come from the old pop-up on the User tab, which was the only place they lived.",
                 "Two corrections while moving that text across. “You” is described as skills you wrote yourself — since 0.99.12 that source deliberately excludes anything a realm got from somewhere else, and the old wording still said “or installed from other sources”. And the marketplace line names its curator rather than assuming Anthropic: the CLI clones whichever directories you configure, and Anthropic’s is only the one that ships by default."]),
    ("0.99.17", ["You can switch straight from one source to another. Picking Anthropic skills or the Claude plugin marketplace greyed out the MCP registry, so getting to it meant going back to All sources first. The cause: with another source named we never query the registry, and the greying read “we didn’t look” as “there’s nothing there”. Only what can be shown to be empty is greyed now.",
                 "A filter with one possibility left greys out whole. Choose Anthropic skills and the type, publisher and category dropdowns go pale together — it’s all skills, all by Anthropic, none categorised, so all three were invitations to change nothing. Ones you’ve already used stay live, so there’s always a way back out.",
                 "“Claude marketplace” is now “Claude plugin marketplace”, which is what it holds. The name also takes effect immediately rather than after the next daily refresh — it used to be read from a snapshot taken when the catalogue was last fetched.",
                 "The registry’s size is counted properly. The count walks the index a hundred records at a time (the API’s ceiling), and the walk used to stop at the first refused page and record what it had — which is why the filter said “MCP registry (100+)” for a source holding thousands. It paces itself and retries now. The sample line quotes that count rather than a number written into the sentence.",
                 "A capability you added to one realm can now be added to the others. The Catalogue reads the same list in every realm — that part was already true — but the Add button didn’t: it shared a test with the “in Cabinet2” mark beside it, so anything added anywhere came back “Added” and greyed out everywhere. The mark still reports every realm, because knowing you have vetted something before is the point of it; the button now asks only about the realm you are looking at.",
                 "The registry’s size was also being read from a snapshot that stopped at 25,000 — which was the ceiling the walk gave up at, not a fact about the registry. A full walk finds 33,657, and the ceiling now sits far enough above that to stay out of the way."]),
    ("0.99.16", ["Catalogue filters grey out the choices that would empty the page. Filter to the MCP registry and Skills and Plugins go pale, because the registry holds neither; pick a type and the sources that can’t supply it go the same way. Each option is costed against the results actually in hand, so the menus describe this answer rather than the catalogue in general. Whatever you currently have chosen is never greyed — filtered into a corner, the page still has to show you which corner.",
                 "The golden page tests no longer go red at midnight. They carried today in them — weekday letters, dates, and which squares in a job’s week strip read Scheduled versus Missed — so the suite failed every morning and the remedy was to regold, which quietly accepts whatever the page has started saying. The render path now reads the clock from one place that a test can pin, and the snapshots are taken at a fixed instant. A snapshot has a time.",
                 "One test had the same rot: it hardcoded a date and passed for exactly one day. It’s relative to now."]),
    ("0.99.15", ["The Catalogue is one list now. It was two rendered one above the other: the mirrored sources went through the filters, and the MCP registry was fetched by a call that only ever received the search text. So filtering to Extensions returned forty registry entries of which thirty-six were connectors — and because the registry joined in only when you named it as the source, CLEARING the source dropped those forty to nothing. Asking for strictly more returned strictly less.",
                 "Registry entries now go through the same filters, the same Suggested ordering and the same pager as everything else, and the registry is in unless you name a different source. One rule with no exceptions, because every version of it with exceptions broke somewhere: choosing a source is narrowing, and narrowing cannot add.",
                 "Publisher and category switch off when the results can only come from the registry, which publishes neither — with the reason on hover, rather than leaving you a choice that can only exclude everything.",
                 "Registry answers are remembered for a few minutes, so changing a filter doesn’t re-ask, and a call that fails keeps the last good answer and says it’s stale. At typing speed the registry starts refusing, and a refused call used to render as “no results” — which is a far stronger claim than we were in a position to make. With nothing cached and no network, the mirrored sources still list and the page says the registry is missing from that answer.",
                 "The User tab’s filters fit on one line again."]),
    ("0.99.14", ["The Catalogue’s filters work again. Yesterday’s release gave them the app’s own dropdown and forgot to ship the script that makes it pick, so clicking an option called a function that wasn’t there and nothing happened. The Capabilities page now loads it.",
                 "The User tab’s filters are the same controls as the Catalogue’s and the Jobs page’s, with a Clear button when something is set.",
                 "An expanded job shows its last 7 runs again — when each ran, how it went, what it said. Yesterday’s week-by-week breakdown was the collapsed row’s strip written out a second time: it answered “how has the schedule been going”, which the strip already answers, and said nothing about the runs themselves. Fewer than seven rows means the job has run fewer than seven times."]),
    ("0.99.13", ["A job’s status now means one thing. The filters read the outcome of the most recent day that actually had one — today or the three before it — which is what the week strip beside the row is already showing. They used to read the last recorded run, so four jobs that had never run all counted as “missed” and filtering on Missed returned every one of them, while the strip marked only two. A job that has never been due now matches no status filter at all, rather than quietly matching Missed.",
                 "The calendar agrees with the strip about what was missed. It had never learned when a job was written, so it counted fire times from before the job existed — one job read “missed four times” on the calendar and “missed once” on the list. A job cannot miss a slot that fell before it was written.",
                 "Expanding a job shows the week day by day, above the run history. A job marked missed opened onto “no runs yet” and nothing else — both true, and together they read as a fault. They aren’t: missed means a scheduled time passed with nothing recorded, which is exactly a job that has never run. It now says so, per day.",
                 "The coordinator wears a laurel beside its name — on the agent page, the Register, the minister cards and the Appoint modal, where it sits next to the checkbox that sets it. It was the word “coordinator” in a pill on the cards and invisible everywhere else.",
                 "Catalogue: sources keep their counts (only types lost them, and for a reason — half of those can’t be counted from the mirror). Long publisher names no longer put a horizontal scrollbar under the vertical one: the menu sizes to its longest option instead of to the control."]),
    ("0.99.12", ["“You” in the Catalogue means you wrote it. Downloading an added Anthropic skill put it in the same folder as the skills you write in a realm, where the two are indistinguishable — so yesterday’s fix had the side effect of listing other people’s skills back to you as your own, offering to move something to another realm that the other realm can already add from its own source. The realm’s record settles it: anything added from a source other than you is excluded, and a skill with no catalogue entry at all — one you wrote by hand — is exactly what the list is for.",
                 "The type filter no longer shows counts. Connectors and Extensions come from the MCP registry, which is searched rather than mirrored, so only two of the four could ever be counted here — and a number on half the list reads as a number on all of it.",
                 "The Catalogue’s filters and search are now the same controls the Jobs page uses, rather than a second set that did the same job and looked different. One definition, used in both places.",
                 "The “View contents” and “Go to file” icons on an expanded skill are smaller, closer to the text they label."]),
    ("0.99.11", ["Adding one of Anthropic’s skills now downloads it. Until today it wrote a catalogue entry and fetched nothing, so the realm listed a skill whose files were still on GitHub — “View contents” had nothing to open, which is how this surfaced, and an agent granted the skill was being told it had one the engine could not load. A listing is not a capability.",
                 "The whole folder comes down, not just SKILL.md: skills routinely reference scripts and templates beside them, and half a skill is worse than none — it loads, then fails at the step that needed the missing piece. If any part of the download fails, nothing is added and the skill isn’t listed as though it were there.",
                 "The one skill already affected — Frontend design, in Cabinet2 — has been filled in. Anything else added this way before today will need adding again.",
                 "The “Origin” row on a capability card is now “Source”, matching the Catalogue’s filter, and for anything added from the Catalogue it names the source you picked rather than defaulting to “Added & authorised in Claude”, which was only ever true of capabilities discovered from the CLI."]),
    ("0.99.10", ["A capability added from the Catalogue is on the User tab instantly. The page refreshes itself in the background while you\u2019re still browsing, so by the time you switch over, the new capability is already there \u2014 badged, switched off and at the top of its section.",
                "The MCP registry shows its size in the sources filter. There\u2019s no total to ask for \u2014 the registry\u2019s API has no stats endpoint and reports no count \u2014 so the daily catalogue job now pages through and counts it, and the menu shows yesterday\u2019s answer rather than a guess. Before the first count there is no number at all.",
                "Skills you wrote have a \u201cGo to file\u201d link on their catalogue cards, opening the folder on disk \u2014 the same link every skill already has in its expanded card on the User tab. The file is resolved by the server from the catalogue entry, never from a path the page supplies.",
                "Agents list: the drag handle now genuinely leads each row \u2014 the previous release said this and the change hadn\u2019t landed \u2014 with the capability counts at the right edge."]),
    ("0.99.9", ["Adding a capability now inspects it, and the risk level is there before you decide whether to switch it on \u2014 which is the only moment a risk level is any use. A remote MCP server says what it is by its transport; a skill is instructions and executes nothing; a plugin gets opened and read, looking above all for hooks, which run on the engine\u2019s events without any agent asking.",
                "What that finds is worth seeing: of Anthropic\u2019s own plugins, claude-security and hookify ship hooks and come out Caution, while the language-server plugins launch a program on your machine \u2014 which their folders don\u2019t reveal, because the binary is declared in the marketplace manifest. A plugin whose files aren\u2019t on this computer is left as \u201cnot inspected\u201d rather than guessed at.",
                "Newly added capabilities arrive switched off, at the top of their section, marked new. Adding is \u201cI want to look at this\u201d, not \u201cI want my agents using it\u201d. The badge clears when the capability is on and at least one agent can use it \u2014 not on a timer, because something you added a fortnight ago and never wired up is exactly the loose end worth showing. The old red \u201cPlanned\u201d label is gone; nothing had gone wrong.",
                "Filtering the Catalogue to the MCP registry shows a sample instead of an empty page, labelled as a sample of over twelve thousand rather than as a shortlist. And the registry has one name again: the pill said \u201copen registry\u201d while the filter said \u201cMCP registry\u201d, which read as two different sources.",
                "Overview: the Claude limit labels are a fixed width, so both progress bars start at the same place instead of wherever the label happened to end.",
                "Agents list: the drag handle leads the row \u2014 picking the agent up is what the row is for \u2014 and the capability counts sit at the right-hand edge."]),
    ("0.99.8", ["A capability\u2019s risk level is now the worst thing it can actually do, and nothing else. The coloured stripe on a card is a summary of the ability icons printed beside it, so a row whose abilities are all amber can\u2019t wear a red stripe and leave you looking for the reason \u2014 which is what the IBKR connector was doing.",
                "That moves IBKR back to Review. A connector exchanging data with a remote service you signed in to is the ordinary case, not the alarming one; if every connector were Caution, Caution would stop telling you anything. The three local MCP extensions stay Caution, because they run code on this computer with access to your files.",
                "Who published something can no longer make it look safer than it is. Provenance decides only the case where nothing is known about what a capability can reach \u2014 it can\u2019t promote something that writes to your disk.",
                "Fixed a capability added from the Catalogue not appearing under User until you reloaded. It was in the realm the whole time; the User tab is drawn by the server and nothing told it to redraw. It now refreshes when you switch back, rather than on every add.",
                "Every legend group reads riskiest-first \u2014 risk, what it runs, and what it can touch \u2014 from the same order the risk level is computed from, so the legend can\u2019t disagree with the badge. Ability icons on a card are ordered the same way, so the first one is the one that set the stripe.",
                "The MCP registry is in the sources filter, which it wasn\u2019t \u2014 it\u2019s searched live rather than mirrored, so it was missing from the menu that filters results plainly on screen. Filter dropdowns are alphabetical now: a dropdown is somewhere you look a value up.",
                "Agents list: the capability counts sit next to the names instead of the panel edge, each in a fixed column so the four numbers line up down the list, with room for two digits."]),
    ("0.99.7", ["Fixed adding anything found in the MCP registry. The registry is searched live and never copied here, so a result you were looking at existed only in the page that drew it \u2014 pressing Add said \u201cno longer in the catalogue\u201d every time. It now asks the registry again and checks the name matches before writing anything.",
                "Fixed the catalogue not recognising capabilities you already use. IBKR is one thing with three names \u2014 com.ibkr/interactive-brokers-ibkr in the registry, \u201cInteractive Brokers (IBKR)\u201d as its title, and \u201cclaude.ai Interactive Brokers (IBKR)\u201d once Claude has connected it \u2014 so comparing identifiers said a connector you had been using for weeks wasn\u2019t in your realm. Anything already in one of your realms now says so, and its button reads Added.",
                "Skills you wrote are in the catalogue, under \u201cYou\u201d. A skill written for one agent in one realm used to be invisible everywhere else, and moving it meant finding the folder and copying it by hand. Adding one copies it into the realm, so an export still carries it.",
                "Sources are named. \u201cMarketplace\u201d wasn\u2019t one \u2014 a machine can have several, and which one something came from is the whole story \u2014 so the filter and the pill both say \u201cClaude marketplace\u201d, or whatever a marketplace you added calls itself. The intro says in one line what each source is and whether anyone vetted it.",
                "Catalogue polish: all four types in the filter (Connectors and Extensions were missing, because they come from the registry rather than the mirrored index), the redundant type pill is gone now that the icon and the filter both say it, the search has a clear button, the filters have a Clear link, and Refresh catalogue has moved to the top right of the section with a name that says what it refreshes.",
                "Capabilities: the risk legend and the risk filter both read riskiest-first, from one definition rather than two hand-written copies that had drifted. The agents list shows how many connectors, extensions, skills and plugins each agent can use, in a fixed column you can scan down. And a System capability shows its own type icon instead of a shield on every row \u2014 the tab already says they\u2019re system ones."]),
    ("0.99.6", ["Capabilities has a Catalogue. Browse what you could add \u2014 316 entries from the Claude plugin marketplaces on this computer and Anthropic\u2019s public skills repository \u2014 filter by source, type, publisher or category, and add one to the realm you\u2019re in.",
                "Searching also queries the open MCP registry, live. It holds over twelve thousand self-published servers, so it isn\u2019t copied here and isn\u2019t browsable: type something and its matches appear in their own section, marked as self-published. With no search term it contributes nothing, because an open registry has no meaningful first page.",
                "The default order is Suggested, and it says why. Anthropic\u2019s own first, then anything already in one of your realms, then publishers with more than one entry, then the rest \u2014 with the reason on every card. Nothing is ranked by popularity: neither source publishes install counts or stars, and an order that claimed to would be inventing it.",
                "Nothing in the Catalogue shows a risk level. Almost none of it has been inspected \u2014 244 of the marketplace\u2019s 297 entries are a repository link and nothing more \u2014 and a Trusted badge on something nobody has looked at is the bug that was just fixed on the User tab. Adding is what inspects it.",
                "Adding puts a capability in the realm and stops there: no agent can use it until you grant it. The filter dropdowns only offer values that exist \u2014 the marketplace lists publishers and categories, the MCP registry lists neither \u2014 so a filter never offers something that can\u2019t match."]),
    ("0.99.5", ["Groundwork for the Catalogue: ARMADA now keeps a list of every capability you could add. It reads the Claude plugin marketplaces set up on this computer \u2014 Anthropic\u2019s official one is there by default, with 297 plugins, 38 of them Anthropic\u2019s own \u2014 and Anthropic\u2019s public skills repository. Nothing is browsable yet; the list is what the Catalogue tab will show.",
                "The MCP registry is searched rather than copied. It holds over twelve thousand self-published servers and grows, which is not a list anyone scrolls and not one worth mirroring onto your machine every night. It is queried when you type, and says so plainly when it can\u2019t be reached.",
                "A new free daily job keeps the list current. Metadata only \u2014 it never installs anything and never touches a capability you already have. It lives with the app\u2019s settings rather than inside a realm, because what is on offer is the same whichever realm you are in; what differs is which of them you chose to add."]),
    ("0.99.4", ["Risk levels say why. Every capability\u2019s Trust level now carries the reason beside it \u2014 \u201cRuns code on your computer, published by third-party\u201d, \u201cReads only\u201d, \u201cNot inspected yet\u201d. A verdict nobody can check is just a colour.",
                "Hooks are recognised as an ability, and they are the serious one. Everything else a capability can reach for waits to be used; a hook runs its own code automatically on the engine\u2019s events, whether or not any agent asked for anything. Anything shipping hooks is Caution, whoever published it.",
                "Fixed capabilities being rated Trusted because nothing was known about them. A discovered plugin had no recorded abilities, and the rules read a blank as \u201cnothing to worry about\u201d \u2014 so every plugin ARMADA found was Trusted by omission, and plugins are the kind that can carry hooks. Unknown now reads as Review: Caution is for what was found, Review for what hasn\u2019t been looked at.",
                "Four capabilities you already have move from Review to Caution: the three local MCP extensions (filesystem, pdf-viewer, windows-mcp), which run code on this computer with file access, and the IBKR connector, which exchanges your data with an outside service. Nothing about them changed \u2014 the old rule only flagged code like this when the publisher was recorded, and for these it never was.",
                "A version scan no longer files capabilities into a realm nobody added them to. The Claude CLI is machine-wide and a realm is not, so installing something while working in one realm used to make it appear, unasked, in the capability list of every other realm you opened next. That list is the record of what you allowed in there."]),
    ("0.99.3", ["Fixed a message vanishing when you left a thread mid-reply. The whole turn was written only once the agent answered, so until then your own message existed nowhere but the open tab \u2014 leave the thread while the agent worked and you came back to a transcript with no sign of what you had asked, even though the status dot was still pulsing. Your message is now recorded the moment you send it.",
                "The thread says what it is doing. Come back to a thread whose reply is still being written and it shows the question with \u201cworking on it\u2026\u201d underneath, and fills in the answer when it lands. The reply streams to the tab that sent it, so a page opened later had no way to know anything was happening; it does now.",
                "A turn that fails now says so in the thread. Before, a run that errored left nothing behind at all \u2014 the message you sent was simply gone, which reads as the app having lost it rather than the agent having had a problem. That included Telegram, where a swallowed message is one you have no way to see again.",
                "If the app is closed in the middle of a turn, the unanswered message is marked as such when you reopen it, rather than sitting there looking ignored."]),
    ("0.99.2", ["A realm can be renamed. Settings \u2192 Realm has a Name field under the picker, and saving it updates the switcher, the window and your agents\u2019 briefings together \u2014 the name lives in two places, and writing one without the other is how a realm ends up with two names on the same screen. The folder it lives in doesn\u2019t change: nothing is keyed on the name, so renaming breaks no job, memory or run report."]),
    ("0.99.1", ["Fixed the type-to-confirm dialog not saying what to type. Deleting an agent or a realm asks you to type its name back, but the box only said \u201ctype to confirm\u201d \u2014 a locked door with no keyhole: the button stayed dead and nothing on screen explained why. It now names the exact word above the field."]),
    ("0.99.0", ["Agents can be retired and brought back. Configure \u2192 Advanced has a Manage this minister section: Retire takes someone out of the realm without deleting anything \u2014 their jobs stop, they leave the register, goals and delegation \u2014 while the threads, memories, run history and capability grants all stay exactly as they are. Reinstate them from Appoint and they come back unchanged, jobs still on the schedules they were on, including the ones that were switched off.",
                "Retiring moves the agent\u2019s folder out of the realm rather than setting a flag on it. Everything that asks who is in this realm answers by listing that one directory \u2014 the scheduler included \u2014 so a retired agent\u2019s jobs can\u2019t fire because nothing can see them to fire. A flag would have meant a filter at every such place, and the one you forget is the one that wakes an agent at 3am.",
                "Appoint is now \u201cAppoint a new minister\u201d and grows a Reinstate tab when there is somebody to bring back. Pick a name and the form fills itself from what that agent actually was, and says what is returning with them \u2014 how many jobs, how many threads, when they were first appointed. There is no tab at all until someone has been retired.",
                "Delete an agent is there too, beneath Retire and worded to be the harder choice: it takes the folder and everything in it. On Windows it goes to the Recycle Bin, and you type the name to confirm. The coordinator can be neither retired nor deleted \u2014 every agent\u2019s briefing names it and goals are assigned through it \u2014 and the page says so where the buttons would be rather than only in an error afterwards.",
                "Run now is dead while a job is switched off, on both the user and system lists. A live button that runs the job, next to a switch saying the job does not run, is two controls contradicting each other \u2014 and the switch is the one telling the truth about tonight. Off now means off from the button as well as from the schedule.",
                "A job whose agent was retired doesn\u2019t come back wearing a fortnight of missed days. It wasn\u2019t missed; it wasn\u2019t due, because its agent wasn\u2019t here."]),
    ("0.98.0", ["System jobs and your agents' jobs are one list. They were the same two facts laid out two different ways on two tabs of one page \u2014 a table on one side, expandable rows on the other. Same header, same columns, same fonts, same week strip now.",
                "What is gone from the System rows is gone for a reason. No Owner: they are all ARMADA, and a column of identical values is decoration. No Last run: the week strip carries the last few days, which says more than one timestamp ever did. And Run now is the same button it is in an expanded user job, rather than a smaller one that does the same thing.",
                "System jobs keep a short run history, so they can draw that strip. They kept only their most recent run before, which is why the list could tell you what happened last and nothing about the days before it. A system job runs on an interval rather than at a time of day, so a day with no record reads as \u201cnothing recorded\u201d rather than \u201cmissed\u201d \u2014 \u201cevery 30 minutes\u201d cannot be late, and marking those red would put a week of failures against every job on a machine that was simply switched off over the weekend.",
                "The switch column is called On/Off on both tabs. The one control in a row that decides whether a job runs was the only thing on the page you had to guess at.",
                "Fixed the Claude limits in the Overview header cutting off the last character of the reset time \u2014 \u201cresets in 5d 17\u201d is not a duration. The box was a few pixels narrower than its longest row."]),
    ("0.97.0", ["The scheduler fires every realm, not just one. Which realm is active decides what the app shows you; it never decided whose jobs run, and now it can't — a realm's schedule is its own commitment, and a job that quietly stops firing because you opened a different realm is indistinguishable from a broken scheduler. One process ticks them all, each with its own timezone, grace period and preflight hold, and one realm failing doesn't stop the next.",
                "Notifications say which realm they came from. Once jobs fire everywhere, “Warren: job failed” on a phone raises a question the message can't answer. Desktop and Telegram notifications now carry the realm's name, test notifications included.",
                "New switch in Realm → Notifications: Notify cross-realms, on by default. On, a realm reaches you wherever you are — a 3am failure in the realm you aren't watching is exactly the one you need to hear about. Off, it only speaks while you're viewing it. Either way the bell keeps every notification, so nothing is lost; it just waits for you there.",
                "Manage this realm now says Export realm, Archive realm and Delete realm. “Delete…” alone, on a page with a dozen other things on it, doesn't say what is about to be deleted."]),
    ("0.96.0", ["ARMADA reopens the realm you were last in. Switching realms only ever moved it for the session: Update & Restart kept the change, but closing the app and opening it again from the shortcut put you back in whichever realm the shortcut was written for — sometimes a realm you had left days earlier, with a full dashboard of someone else's jobs on it. The active realm is now remembered on the machine, so both ways of restarting agree.",
                "Naming a folder still wins — `matcap app \"D:\\Work\\Hand-realm\"` opens that realm, and it becomes the remembered one. With no folder named and nothing remembered yet, ARMADA lists the realms it knows about rather than guessing at one.",
                "Fixed the tests writing to the app's own settings file. Anything a test did to the app root, the theme or the active realm changed them for real on the machine running the suite."]),
    ("0.95.0", ["Agents no longer speak. Read-aloud worked, but it did not sound like something worth shipping: numbers came out digit by digit, the intonation was flat whatever was being said, and stray symbols were read out by name. Those are not polish problems — they need a text-normalisation stage and a better engine — so the feature is out of the app rather than sitting in v1 half-good. Nothing else changes; the Voice box, the switch beside the gear and the voice settings on each agent are simply gone.",
                "The work is written down rather than thrown away. What was built, what it cost, which Windows voices are unreachable and why, and the order to pick it up again are all recorded, so bringing it back when a better voice engine exists is a decision rather than a rediscovery."]),
    ("0.94.0", ["Read-aloud has a switch in the thread, next to the gear, for any agent with a voice. It starts off every time you open the app — giving an agent a voice says it can speak, not that it should start talking the moment you arrive — and switching it on reads the reply already on screen, so you find out it works straight away. The old speaker in the thread header is gone: two controls for one behaviour, a few centimetres apart, is worse than either.",
                "Replies are cleaned before they are spoken. A voice reads a web address one character at a time, announces emoji by name, says “dash dash dash” at a horizontal rule and turns a table’s pipes into noise. Links, file paths and email addresses are now named rather than recited, decoration is dropped, and “too_expensive” is read as two words.",
                "Fixed an agent’s reply failing to speak at all when it contained a curly quote or a minus sign. Two separate faults: text was being handed to Piper in the Windows locale encoding rather than UTF-8, and Piper’s own pronunciation stage rejects typographic quotes. Both are handled before synthesis now, and a failure says what went wrong instead of leaving you looking at a switch that appears to be on.",
                "Hear it shows a spinner while it works. Piper takes a second or two to generate audio before any sound arrives, and a button that does nothing visible for two seconds is a button you press again."]),
    ("0.93.1", ["Piper is now set up once per computer rather than once per realm. Pinning its location to a realm was wrong: it meant configuring it again for every realm you own, and being told “not installed” in whichever one you happened to be looking at — which is exactly how a voice download ends up in a folder the app never reads. The path lives in the app’s own settings now, a realm can still override it, and voices are found in both the realm’s folder and a shared one, so a 60MB download is available everywhere.",
                "When Piper has nothing to offer, the Voice box now names every folder it searched and says which of the two things is missing — the program or the voices. “No voices installed” with no folder beside it is not a message anyone can act on."]),
    ("0.93.0", ["Agents can speak with Piper, a local neural voice engine that sounds like a person rather than a 2013 phone menu. The Voice box has a Provider setting: Windows voices, which need nothing installed, or Piper, which you install once and then costs nothing and never leaves the machine. Each agent still picks its own voice, so a cabinet of eight can be eight different people.",
                "ARMADA does not ship Piper and never loads it into itself — it runs the program you installed, hands it text and gets audio back. That distance is deliberate: Piper is GPL-3.0, ARMADA is free for personal use, and two programs talking to each other is the arrangement where that difference stays simple. Nothing about your setup changes if you never install it.",
                "Voices live in the realm folder, so a realm you copy to another computer brings its voices with it. The picker lists what is actually installed, names them readably (“Alan · en-GB · medium”), and says what is missing when Piper is not ready rather than offering a voice that cannot speak."]),
    ("0.92.1", ["Corrected what the Voice box says about getting better voices. It pointed at Narrator’s “Add natural voices”, which was wrong: those install as app packages and register no speech token anywhere, so they are invisible to every application except Narrator itself — measured here with two of them installed and present in neither of the two APIs a browser can reach. The link now opens Windows’ speech settings, where voices that apps can actually use are installed, and the text says plainly that the Narrator ones are not among them."]),
    ("0.92.0", ["The voice picker has a refresh, and a link to where voices come from. A voice installed while the page was open was not in the list the speech engine handed us at load, and the only way to find it was to reopen the app — on a form you may have half-edited. The refresh really re-asks the engine rather than replaying its cached answer, and says so plainly when nothing new turned up. “Add natural voices” opens Accessibility → Narrator, where Windows installs the good ones for free.",
                "Verbosity now counts towards an agent’s relative token consumption, alongside its model and effort — the marker moves when you change it, on both the agent’s Configure page and the realm defaults in Settings. Effort buys thinking and verbosity buys writing, and the reply is the smaller half of what an agent produces: verbosity gets a 1.6× span against effort’s 10×, so a detailed low-effort agent still reads as cheaper than a terse high-effort one. Those numbers are a considered estimate, not a measurement — run telemetry records tokens but not the verbosity that produced them — which is why the widget says “relative”."]),
    ("0.91.1", ["Fixed the status filter offering colours the strips stopped using two revisions ago. The dropdown kept its own table of flat colours, so Success was a solid teal in the menu and a pale green tint in the row a centimetre below it, and Missed was a grey square rather than the crossed circle. Menu and legend are drawn by one function now, on every job page.",
                "A capability opens from the left. The chevron sat past the on/off switch and the bin — the control that opens the row was the last one you reached, and capabilities and jobs opened from opposite ends of the row. The type icon moved in beside the name, rather than holding a column that put sixteen pixels between an icon and the thing it labels.",
                "An agent’s own Capabilities tab carries the legend the realm page has. The cards are the same cards, with the same risk stripe and the same ability icons, so reading them took a key that was only on the other page.",
                "“Check for updates” now says “Check for version updates” — it checks the capabilities you have installed, not ARMADA itself."]),
    ("0.91.0", ["Agents can speak. Switch Voice on in an agent’s Configure page, pick a voice and a speed, and it reads its replies aloud while you’re in the chat. It uses a voice already installed on this computer, so there is nothing to install, nothing to pay for, no key to store and nothing sent anywhere — and each agent gets its own, which is the point when the cabinet is eight different people.",
                "Windows ships better voices than the ones it starts with: Settings → Accessibility → Narrator → Add natural voices. They are free, they work offline, and they appear in the picker once installed.",
                "Code blocks are never read aloud, and a reply is spoken once — the speaker button in the chat header mutes it for this browser without changing how the agent is set up. A job that runs while the app is closed stays silent; this reads the chat, not the scheduler.",
                "It is a proof of concept, and it speaks a reply once the reply is finished rather than as it arrives. The setting records which provider is doing the speaking, so a local engine or a paid voice can be added later without touching any agent already configured."]),
    ("0.90.2", ["A minister’s role title fits on one line again. The week strip was a column of its own, which narrowed every line beside it and not just the ones tall enough to touch it — so “The Hand (Prime Minister)” broke across two lines in a card with plenty of room. The strip now floats to the top right, and the role, model and profile all run the full width underneath it.",
                "They keep the portrait’s indent rather than starting at the card’s left edge, which leaves the whitespace the card was missing."]),
    ("0.90.1", ["The week on a minister’s card and in the Register is the last seven days and nothing else. It was borrowing the Jobs list’s window, which runs three days back and three forward — but on a card the strip is a log, and half of it was a forecast sitting in a column headed “status”. Worse, the rollup was pasting that centred week onto its own list of dates, so last Wednesday wore next Wednesday’s mark.",
                "The card dropped the day initials — every square is a day that has already happened, so they only repeated the tooltip — and the strip now sits level with the name. Model, effort and profile moved below it and take the card’s full width, which is what the profile needed to read as a sentence. In the Register the column is headed “7D job status” for the same reason.",
                "A square’s tooltip says “Job scheduled” rather than “Scheduled”, which beside a date read as a property of the date.",
                "The Register shows active jobs as a pill like the goals count beside it, instead of a bare digit that looked like a different kind of fact.",
                "The Overview header no longer shifts after it loads. Everything in it except the title arrives from a fetch — the KPI values from one, the limit bars from another — so the bar grew twice, a second apart, and pushed the grid down each time. It now reserves the space it will need.",
                "Leaving section-edit mode has its own icon, a struck-through pencil, and the button keeps the same background throughout — tinting it made the same control look like two.",
                "The cost pill reads “uses quota” behind a small dial, and the Jobs legend says “-/+3D job outcome and outlook”, which is what that strip actually covers."]),
    ("0.90.0", ["The seven-day strip on a minister’s card and in the Register now shows the same thing the Jobs page shows. Both were drawing their own week from run-reports alone, which knew nothing about what was scheduled — so an agent with nothing due looked identical to one that had missed every run, and the card could describe a week differently from the Jobs page for the same agent. There is one implementation now, with the day initials and today marked.",
                "An agent owns several jobs and has one row of squares, so each day shows the worst of them, in this order: missed, failed, warning, running, succeeded, scheduled, nothing due. The question a card answers is “is anything wrong over there”, which is the worst case rather than the average. A job that is switched off is not due, so it cannot be missed.",
                "In the Register, autonomy moved next to the name and gave up its column. It is an icon and a property of the agent; the week needed the room more."]),
    ("0.89.1", ["The Overview no longer ends in a hard cut. A solid 20px band of page background sat below the grid, so whatever happened to be at the bottom — usually the job calendar’s status legend — lost its lower half: not “there is more below”, just text with its descenders missing. The band is a fade now, and the grid scrolls the same distance further, so at the end of the scroll the last row clears it completely.",
                "The Overview header’s shadow reaches both window edges. It started 24px in from the left and ran to the right edge, which drew half a line — the header is pulled out to the edge and re-pays the indent as padding, so nothing in it moved."]),
    ("0.89.0", ["The Jobs page and an agent’s Jobs tab are one list. They had drifted into two readings of the same job: the realm page was a sortable table with a Created column and a last-run dot, whose rows threw you onto the agent’s page when clicked; the agent’s tab was expandable rows with the cost per run, the next run, a seven-day strip and an on/off switch. Only one of them let you do anything. It is now one renderer, so the two cannot drift again.",
                "The realm list adds Kind and Owner, between the job name and its cadence — the two facts an agent’s own page answers by being that agent’s page, and the reason that list needed to be different at all. The other columns tightened slightly to make room.",
                "Clicking a job on the Jobs page now opens it there instead of navigating away, with the same Run now, Edit job, Delete job and run history you get on the agent. Edit still goes to the job’s own page, from either list.",
                "Created moved out of the list and into the job page’s header. It is worth knowing once, while you are looking at one job; it was not worth a column on a page you scan. Sorting by Cost and by Next run now sorts by the number rather than by the label — “≈14k / run” and “Mon 9/21, 20:00” do not sort as themselves."]),
    ("0.88.0", ["Fixed an agent with a large context failing every turn. Windows caps a command line at 32,767 characters and the agent’s whole assembled context — covenant, soul, mandate, tenets, memories, capabilities — was being passed as one argument on it. The Minister of Finance had grown to 34,494 characters, so every run died instantly with “[WinError 206] The filename or extension is too long”, which names neither the flag nor the cause; the other seven ministers were sitting between 21,000 and 25,000, one memory away from the same wall. A context over 12,000 characters now travels to Claude Code in a file. This also explains a usage panel reading zero for a day you know you used it: the turn never ran, so there was nothing to count.",
                "Fixed chat turns that arrive outside the app spending tokens invisibly. Two paths run a conversation — the one the app streams, and a plain one used by Telegram and the API — and only the first wrote a run-report. The second returned the token count to its caller and dropped it, so those turns cost real quota and left the day showing nothing.",
                "The buttons on a job’s own page are the same size as the ones in an expanded job row, and Delete job sits in the line with the others rather than pushed to the far edge. Same four actions, two views — they shouldn’t look like two products.",
                "On a minister’s card, the appointment moved under the portrait, icon over date. It had been at the far end of the footer, competing with the counts for your eye without belonging to them; it is a fact about the person, so it now sits with the face.",
                "The card footer carries the number of jobs that are switched on, and splits into two groups: goals, memories and jobs on the left, then a gap, then connectors, extensions, skills and plugins on the right. What the agent is working on reads apart from what it can reach. The plain job count above the footer is gone — two counts of the same thing on one card, disagreeing about whether a paused job counts, is worse than one."]),
    ("0.87.1", ["A job that didn’t exist yet is no longer marked as having missed its run. The week strip worked back from the schedule alone, so a job created this morning showed three red days behind it while the run history underneath correctly said it had never run — two readings of the same job, on the same page, disagreeing. Fire times that fell before the job existed now read as Not scheduled: there was nothing there to miss. It is checked per fire time rather than per day, so a job written this afternoon isn’t marked as having missed this morning either.",
                "The missed marker is now a filled circle with a cross in it rather than a hand-drawn ×, and the legend draws the same glyph the strip does. A legend that approximates its own key is a legend you have to interpret.",
                "The job expander is the same chevron capabilities use. It had been the up/down unfold arrows, which say “this opens both ways” about a row that opens one way.",
                "Delete is a labelled button rather than a bare bin icon. It sits with Edit under an opened job, where the label has room and the consequence is worth spelling out.",
                "The job’s own page was rearranged: Run history now sits directly under the prompt instead of below the settings, and Save, Run now, Back and Delete job are collected in one bar at the foot. The buttons had been scattered down the page in the order the sections happened to be written."]),
    ("0.87.0", ["The 7-day strip is now centred on today: three days behind, today marked, three ahead. The trailing week only told you how it had been going, which the run history already did; the centred one uses the same seven squares to show what has happened and what is coming. This applies to the realm Jobs page too, so the two still agree.",
                "A missed day carries a \u00d7. Missed and Not scheduled were two faint greys a shade apart, so \u201cthis should have run and didn\u2019t\u201d looked like \u201cnothing was due\u201d unless you had the legend open beside you.",
                "The job row shows when it runs next instead of when it last ran \u2014 the last run is already in the week strip and the history below, and the next one was the thing the row couldn\u2019t tell you at all. A job that\u2019s off says so; one with no schedule says on demand.",
                "The expand chevron moved to the left of the job title and the duplicate on the right is gone. Delete moved out of the collapsed row and now sits beside Edit in the expanded view, where it belongs with the other things you do to a job you\u2019ve opened and read. The legend is right-aligned over the strip it explains."]),
    ("0.86.1", ["Each job row now shows what one run of it costs. A command job is free; an agent job that has run says roughly how many tokens it takes — the median of its own recorded runs, so one unusual first run doesn't set the expectation for all the others. A job that has never run says it uses your quota and leaves it there rather than estimating from nothing.",
                "Job rows carry the 7-day health strip and its legend, the same one the realm Jobs page uses, computed by the same code. Two implementations would eventually show the same job having had a different week on two pages.",
                "Delete moved into the row as the same red bin icon capability rows use, beside the on/off switch. Since an icon has no room for a warning next to it, the confirm opens a small bar above the row naming the job, and clears itself after a few seconds.",
                "The Created column made way for Cost. It was the one column nobody was reading, and both cost and recent health are things you might act on."]),
    ("0.86.0", ["Jobs can be switched off. A job that's off stays in the list, greyed, and simply doesn't run on its schedule — Run now still works, so it's a pause rather than a delete. Until now the only ways to stop a job were to delete it or edit its cron away, neither of which is what you actually wanted.",
                "Job rows now open the same way capability rows do: the same chevron, the same rotation, and an on/off toggle in the same place. The summary moved under the title as a subtitle, which gives the name back the width it was sharing with a sentence.",
                "An expanded job shows its prompt as content rather than as a form field. It was a read-only text box, which looks exactly like something you can type into — you can't, and nothing told you so. It still scrolls and still drags to resize.",
                "Jobs can be deleted, from the row. It asks twice and names the job on the second press, and it keeps the run history: that's a record of what actually happened, and deleting it because the job was retired would quietly falsify the telemetry.",
                "The Overview header now reads Active jobs and counts only the ones that are on. It was counting every job that existed, which is a different question."]),
    ("0.85.1", ["The system-jobs table now says when a job will actually run — \"Mon 9/21, 20:00\" — under a column called Next run. It used to say \"due now\", which describes the scheduler's internal state rather than answering the question the column asks; a job whose time has passed runs on the next sweep a minute later, so it now says \"any moment\" and everything else gets a time you can plan around.",
                "Jobs have a summary: one line saying what the job does, shown beside its name in the list. A list of names tells you what your jobs are called, not what they do, and with prompts running to a couple of thousand words the only way to find out was to open each one.",
                "The \"Run (mock)\" buttons are gone and the real one is now \"Run now\". The mock engine was useful when jobs were being wired up and is just a way to get a fake answer now."]),
    ("0.85.0", ["The Claude usage bars no longer go dark between agent runs. They are read using the sign-in Claude Code keeps on this machine, which lapses after about half a day — so unless you'd run an agent recently, the header just said the figures would update when one next ran. Two changes fix it. A new background job asks Claude for a single word every eight hours, which makes Claude Code renew its own sign-in as a side effect: measured at nearly eighteen hours bought for a five-second call, so a few tokens a day. And every successful reading is now kept, so if the live one ever fails you still see the numbers, labelled with how old they are and faded once they're past six hours, rather than an empty space.",
                "ARMADA still never touches Claude Code's stored credentials. It would be easy to renew the sign-in directly, and it is a trap: the refresh token is usually single-use, so spending it without writing the replacement back would break your Claude Code login. Asking Claude to do a trivial piece of work lets it manage its own credentials, which is the only safe version of this.",
                "Fixed the page snapshots failing every time the date changed. Today's date is rendered into the artefact filters, so the first test run after midnight compared a page containing today against a snapshot containing yesterday and failed three checks that had nothing wrong with them."]),
    ("0.84.5", ["The workspace folder moved into Advanced on the Realm settings page, under its own \"Workspace & portability\" heading. It's the one setting on that page about the machine rather than the realm, and sitting under Realm identity it read as a routine field — it is neither routine nor identity. Opening Advanced there now scrolls it into view, the same as on an agent's Configure page."]),
    ("0.84.4", ["Lists written across more than one line now render as one list. Documents wrap at column 95, so a numbered point routinely spans two or three lines — and only the first was being treated as part of the item. The rest appeared underneath as a stray paragraph, and because that paragraph broke the list, every numbered item started counting again from 1. Both faults came from the same missing rule.",
                "Clicking outside a document field now leaves edit mode and shows your text rendered, marked \"unsaved\" until you save it. So you can check how a heading or a list came out without committing to it — and the rendering comes from the server, the same one the page uses, rather than a second renderer in the browser that could quietly disagree with it.",
                "Save and Cancel now sit side by side, and opening Advanced scrolls it into view rather than leaving it below the fold. The page also breathes a little more between sections."]),
    ("0.84.3", ["Fixed apostrophes and quotes turning into \"&#x27;\" on an agent's Configure page. The text was being HTML-escaped once before the field and once inside it, so the reader showed the escape codes — and the edit box decoded one level, meaning the next Save wrote those codes into the file. Text is now escaped once, at each place it's used. Marcus's three documents had picked up the damage and have been repaired.",
                "Save and Cancel are now pinned to the right of the Configure form and stay with you as you scroll. The page runs to an avatar, eleven fields, three documents and two collapsible boxes, and Save sat under the last of them — so committing a one-word change to the Name meant scrolling past everything you hadn't touched.",
                "Saving keeps you on the page and shows a Saved tick, instead of bouncing you back to the agent. Editing a character happens in passes, and every save was costing you your place. The three documents drop back to their rendered form using HTML from the save response, so what you see confirmed is what was written."]),
    ("0.84.2", ["Soul, Role and Mission and Tenets are editable by clicking the text. The Edit link is still there, but a block of prose that looks like a document should behave like one. The field also keeps the height it had while you were reading it — it used to snap down to its minimum the moment you clicked, so a long Soul collapsed into a small box and the page jumped under the cursor.",
                "The Covenant now carries the date it was last changed, on the Memory page and in its reader. Governance you can edit needs a date on it, or there's no way to tell a text you considered last week from one you haven't looked at in months.",
                "An agent's Overview tab is gone. It was a read-only digest of the Mandate, Soul, Jobs, Memory and Skills — every one of which now has its own tab that shows more and lets you change it — so it had become a worse copy of five pages you already have. Old links to it open the agent's Threads."]),
    ("0.84.1", ["An agent's Soul, Role and Mission and Tenets now read as prose. They're written in headings, lists and emphasis because they're meant to be read, and the Configure page was showing you the source — which is also the version you'd proof-read. They render by default and turn into raw markdown only while you're actually editing. The Covenant's Read view does the same; it was falling back to showing hashes and hyphens.",
                "Agents appear in the same order everywhere: the coordinator first, then everyone else alphabetically by name. Each list used to sort itself, so the Ministers grid led with the coordinator while the Memory sidebar and the capability roster went by folder name — three views of one cabinet in three different orders, with nothing to point at as the right one. Ibn Battuta now sorts under I rather than under 'travel'."]),
    ("0.84.0", ["The realm's Covenant — the terms every agent in it is bound by — now has somewhere to live. It loads into every agent's context ahead of their own mandate and tenets, which makes it the highest-leverage text in a realm, and until now it was the only realm-wide document with no screen at all: goals have the Goals page, realm memories have the Memory list, and this was editable only by opening a file on disk.",
                "It sits pinned at the top of the Memory page, because that page already means \"what every agent always knows\". It's deliberately not styled as a memory card: memory is facts that change, this is governance that shouldn't. And unlike System memory, which ARMADA generates and keeps read-only, the Covenant is yours to write — read or edit it in place.",
                "Two smaller signposts. The Ministers page carries a single line saying every minister is bound by it, rather than reprinting three thousand characters over a page you use to pick someone. And the Tenets box on an agent's Configure page now says the Covenant already applies — that box being exactly where you'd otherwise paste the same honesty and loyalty rules into all eight agents."]),
    ("0.83.1", ["Status dots now mean what the legend above them says. A job that had finished cleanly was showing the colour for \"running\", and a job actually running showed the colour for \"warning\" — the dots and the legend were being coloured from two different palettes that had ended up crossed, with the key to read them by sitting a couple of inches higher on the same page. One palette now, and a test holds the two together."]),
    ("0.83.0", ["Token counts are real again. A run was reporting a handful of tokens next to a cost of dollars — and the cost was the honest one. Two things were being left out. A turn quietly uses a second, smaller model for background work, and those tokens were never counted. And the first time a thread sees its context, that context is written *into* the cache rather than read from it — so on a new thread the entire prompt was landing in a column nothing was adding up. A real turn that reported 6 tokens had used 2,954.",
                "Both ways ARMADA runs an agent now share one piece of accounting, taking the per-model totals the engine already provides, so they can't drift apart again. Usage, the Register's token column and the API-equivalent figure all get the corrected numbers; runs recorded before this keep what was stored at the time, so expect a step up rather than a smooth line."]),
    ("0.82.6", ["Capability rows hover like the agent cards on Ministers — a defined edge and a slight lift, instead of a background tint that washed out the risk colour just as you pointed at it. The colour band down the left of each row is also a touch wider than it was."]),
    ("0.82.4", ["An agent's Capabilities page is now just that agent's: what it can use, and a count of what else the realm has. It no longer reprints the rest of the catalogue, and the Manage button, the connector refresh and the per-card controls are gone from it — all of those belong to the realm Capabilities page, and having copies here meant three places to do one job, with the copies being the ones that misbehaved.",
                "The capability counts on an agent's card and its Capabilities tab now count what that agent can actually use. They were counting the whole realm, so every agent showed the same figures — a number about the realm wearing a label about the agent.",
                "Fixed empty sections vanishing for good once you used a filter. A section with no capabilities in it has nothing to count as visible, so it was hidden and could never come back — clearing the filter didn't bring it back, and only something re-rendering the page did. Empty sections are part of the page when nothing is filtered, and out of the way when something is.",
                "The risk-colour tint down the left of each capability is wider and easier to see."]),
    ("0.82.3", ["Refreshing connectors no longer files every tool as a Connector. A local tool that runs on your machine is an Extension and a remote service is a Connector — ARMADA knew that rule but the refresh button didn't use it, so pressing it added a second copy of each local tool, labelled as a remote service, alongside the correct entry. Refresh now uses the same rule as everything else, and clears up duplicates a previous refresh left behind, so a realm already affected repairs itself the next time you press it.",
                "This mattered more than a cosmetic mislabel: the realm catalogue is what capabilities are granted from, so two entries for one tool meant granting one of them and silently getting nothing."]),
    ("0.82.2", ["An agent's own Capabilities tab now shows what that agent can actually use. It still said realm-wide tools were inherited by every agent and listed the whole catalogue — true before capabilities were granted one at a time, and the opposite of true now. Worse, it meant this page and the realm Capabilities page disagreed about the same fact while each looked authoritative. The realm catalogue plus what you've granted is the source of truth, and this reads from it. Underneath, what the agent can see but not use is listed too, since that's the more useful half once access is something you hand out deliberately.",
                "A capability card no longer snaps shut when you drop an agent into it. Granting reloads the page, and a reload returns every card to closed — including the one you were working in."]),
    ("0.82.1", ["The Capabilities page now shows who each capability is available to, and lets you change it by dragging. Collapsed, a row reads \"Marcus + 2 agents\" — or just a count where there's no coordinator to lead with. Open one and there's an Available-to line of agent pills: the coordinator pinned and greyed because you can't take that away, everyone else removable. It's the same pill and the same roster as Goals, because attaching a person to a thing is one idea and it should feel the same in both places.",
                "Drag an agent from the roster onto a capability to give them access. The three risk levels moved onto one line to make room for the roster beside the legend, and each capability row now carries a sliver of its risk colour fading in from the left edge — so a card and its swatch in the legend read as the same object.",
                "The filter that said \"All owners\" now says \"Available to\" and lists every agent, which is the question the page actually answers: pick Warren and you see what Warren can reach. And a capability you've granted to three agents is listed once, on the realm card, rather than reprinted under each of them as though it were theirs alone."]),
    ("0.82.0", ["Capabilities are now granted to agents one at a time instead of shared by everyone. The realm holds the catalogue — everything discovered, installed or imported lands there — and an agent can use a capability only once you've given it that one. Your coordinator is the exception: the PM's job is to see across the whole realm, so it keeps the lot. A realm with no coordinator has no agent with blanket access.",
                "This reverses how it worked before, and the reversal is the point: an agent with nothing set used to inherit everything, and the only way to stop it was switching a capability off for the entire realm. Now an agent starts with nothing and every addition is a decision you made. Withholding is real for connectors and extensions — the tools are kept out of the run, not just left off a list. Skills and plugins have no equivalent per-call handle, so for those a grant controls what the agent is told it has.",
                "Agents can still see the whole catalogue, because one that can't know a tool exists can never ask for it. What they can't do is reach for it: they're told plainly which ones aren't theirs, and that the way to get one is to ask you, with a reason, for the task in front of them. Approving lands in the bell like any other approval, and the capability is theirs from the next run.",
                "Capabilities an agent picks up this way are marked new in the thread's Capabilities panel, so an agent doing its job and an agent's reach growing don't look identical. Importing from Claude Desktop or the CLI adds to the realm catalogue and grants nobody anything — the same rule, so an import can't quietly hand eight agents a new tool."]),
    ("0.81.1", ["Agents are now told where their output belongs: inside ARMADA's root folder, in their own working folder unless you name somewhere else. Reading outside stays normal — plenty of work needs it — but writing outside is what scatters a realm across a disk, so it ends up un-findable, missing from a backup, and left behind when the realm is deleted.",
                "It's a working agreement rather than a lock, and it's described that way rather than pretending otherwise: an agent with a shell or desktop capability can reach the whole machine, and no rule ARMADA writes changes that. What ARMADA does instead is notice. A run that writes outside the root records it on the run report and in the log, so a stray file is something you know about rather than something you find months later."]),
    ("0.81.0", ["ARMADA now has a root folder: the one place on this machine it works in. You pick it once, in App settings, and every realm lives inside it. Adding a realm from somewhere else is refused outright, with a note saying where to move it — rather than being accepted and half-working, which is how you end up unable to answer the only question that matters: what can this thing actually reach. One folder to point at, and one to back up.",
                "A realm outside the root is a blocking problem, so it shows on arrival and holds that realm's scheduled jobs until it's fixed. Moving the root re-checks the realm you're looking at straight away, since moving it can put that realm outside."]),
    ("0.80.2", ["ARMADA clears up temp files left over when it was killed mid-save. Every save writes to a temporary file first and then swaps it into place, so a crash can never leave you with half a file — but if the process is killed between those two steps the temporary one stays behind, and nothing ever collected them. One realm had 67, five days' worth. The scheduler now sweeps them when it starts, leaving anything less than an hour old alone in case another process is mid-write."]),
    ("0.80.1", ["Telegram no longer repeats a notification it just sent. Identical alerts have always collapsed on the desktop so a job retrying in a loop couldn't carpet the screen — but that was never applied to Telegram, the one channel that follows you out of the building. It could go quiet on the machine in front of you and keep buzzing your phone. Both channels now behave the same way, and each keeps its own tally so silencing one doesn't silence the other. The in-app feed still records everything: it's the archive, not an interruption."]),
    ("0.80.0", ["A realm can move to another computer. Export it, extract it on the new machine, point ARMADA at the folder — and the jobs work. What used to stop that was the text of the jobs themselves: prompts name folders like D:\\Work\\Finance, and on another machine that folder is somewhere else. Realm settings now has a Workspace folder, and a job prompt can say {workspace} instead of a drive letter; ARMADA fills in the real path when the job runs. Set the folder once on the new machine and every job follows it.",
                "There's a button to convert the jobs you already have. It shows you exactly which files it would touch and how many references are in each before changing anything, because it's your prompt text it would be editing. Thread history and memory are never rewritten — what an agent was told at the time was a real path, and tidying the past would just be forging the record.",
                "Adding a realm now checks whether it can actually run here, and says so on the spot: engine, workspace folder, whether the agents and jobs are readable, whether Telegram is linked. If something essential is missing the scheduled jobs are held rather than left to fail every night until you notice — and fixing it releases them straight away, with no switch to remember. Telegram not being linked is a warning, not a blocker: the work still happens, the notifications just stay in the app."]),
    ("0.79.7", ["Running ARMADA's own tests no longer sends you Telegram messages. Bot credentials live outside every realm — that's what stops a realm export carrying your token to another machine — but it also meant a test inventing a realm in a temp folder found your real bot and messaged your real phone, because \"a job failed\" is set to reach Telegram by default. Every run of the suite sent a few. There's now a switch that mutes anything leaving the machine, the tests set it, and a test that reaches the network fails instead of quietly buzzing you."]),
    ("0.79.6", ["Exporting a realm now tells you if anything didn't make it into the archive. A file it couldn't read — one being written at that moment, typically — was skipped and the export still reported plain success, so a backup with a hole in it looked identical to a complete one. You'd find out when you restored it. It still doesn't abandon the whole export over one locked file; it names what it missed and suggests exporting again."]),
    ("0.79.5", ["Scheduled jobs now record what they produced. A job that wrote a report left the report on disk and no trace of it in the thread — the Artefacts rail and the Capabilities section only ever filled in from chat, which is backwards: when you're sitting there you can watch the file appear, and when a job runs at 03:00 the thread entry is the only account you get. Fifty-two job runs in this realm had produced exactly zero recorded artefacts. Messages arriving by Telegram were in the same position and are also covered now.",
                "Telegram turns are also held to the memory boundary. Every other way of reaching an agent reverts a write into another agent's memory folder; that one path didn't, so it was the way around a rule the rest of the app enforces. All three routes into an agent — the app, a job, Telegram — now run the same capture and the same guardrail, rather than three near-copies that had already drifted."]),
    ("0.79.4", ["The Cadence filter on the Jobs page no longer sorts a job by how its schedule happens to be written. It recognised one spelling of \"every weekday\" and treated every other way of writing the same thing as weekly — and a job running Monday to Saturday was filed as rarer than one running Monday to Friday, so filtering for the jobs that run most days hid the one that ran most of all. It now counts the days a schedule actually covers."]),
    ("0.79.3", ["The model on an agent's card is now the model that runs. Picking \"Claude Opus 4.8\" quietly ran whichever Opus was newest — the run records show agents set to 4.8 answering on Opus 5 — because ARMADA translated the name into the family \"opus\" and let the engine choose the version. It only knew the exact name of a handful of models, and everything else fell through to the family. It now reads the model list it already syncs from your account, which is the list the names came from, so a version you pick is the version you get.",
                "Family names are still the fallback when a model isn't in that list, since they always work — but they're the exception now rather than what happened to every model but four.",
                "The Register's per-agent token column now covers the same 30 days as the header above it. If you've ever reset usage, the header started counting from the reset and the column counted everything on disk — two totals on one screen, both labelled /30d, and in this realm they differed by more than double. The reset is a single line now, so every figure honours it."]),
    ("0.79.2", ["\"Anthropic's model list wasn't reachable\" was often untrue. The catalogue refresh had six ways to come back empty and reported them all as a network fault — including the ones where ARMADA never made the request: sync switched off, no Claude sign-in, or a sign-in mid-refresh. It now says which, and the three that fix themselves are no longer recorded as failures at all, because nothing is broken.",
                "System jobs stop crying wolf. These refresh cached data on a schedule, so a single miss is invisible and usually gone by the next pass; ARMADA now records it on the Jobs page straight away but only raises a notification once a job has failed three times running, and says so when it does. A bell that rings for things that fix themselves is the same as no bell, because you stop reading it."]),
    ("0.79.1", ["Approval notifications now tell you what you're approving. They used to arrive as \"Needs your approval\" and the agent's folder name plus the proposal's title — so a job an agent called \"x\" reached you as the letter x. You now get which agent proposed it, whether it's an agent job or a script, when it would run in plain words (\"every weekday at 07:00\"), and what it would actually do — enough to decide without opening the app, which matters on Telegram where there's nothing to click through to. A proposal with nothing in it says so, rather than looking like a formatting glitch.",
                "Every notification ARMADA sends now goes through one composer, so job events and approvals can't drift apart again."]),
    ("0.79.0", ["Fixed command jobs that call ARMADA's own tools failing with \"No module named matcap\". Python only looks in the current directory, and a command job runs in your realm rather than in ARMADA's own folder — so a job invoking ARMADA worked or didn't depending on where it happened to be started from, and the error looked like a broken Python install. ARMADA now tells the job where it lives.",
                "Agent jobs get twenty minutes instead of five before being given up on. Five was short enough that a scheduled brief doing real work — searching, reading files, writing a report — could be cut off after doing most of it, and the failure looked identical to a job that was genuinely stuck. A job can set its own limit, or a realm can set a default for all of them.",
                "Job notifications now follow one template and actually say what happened: which job, which agent, why it failed, and how long it ran. They used to be assembled differently in each place, so a failure could arrive as nothing more than the agent's name and an exception type — which is the whole message when it reaches you on Telegram, where there's no page to click through to. A failed script now reports the error from its output rather than the last thing it managed to print before dying."]),
    ("0.78.1", ["Fixed the colour mode. Choosing System snapped straight back to Light, and Light and Dark only held until you clicked something else — the choice was written to browser storage that nothing ever read, so it was really a property of the address Settings happened to navigate to rather than a setting. It's saved on this machine now, next to the colour theme, and applies to every page. System is resolved in the browser before the page paints, so there's no flash and no ?dark in the address bar; change your OS between light and dark mid-session and ARMADA follows without a reload.",
                "Telegram moved to sit under Engine in App settings — both are about what ARMADA is connected to, and it now reads above the Notifications section that refers to it."]),
    ("0.78.0", ["Telegram replies back straight away. ARMADA now holds a connection open to Telegram rather than checking once a minute, so \"Sent to Warren — answers usually take 30–90 seconds\" lands within a second or two of your message instead of arriving a minute later, when it no longer tells you anything. The listener runs in the scheduler, the always-on process; if that isn't running, the old once-a-minute check still covers for it, and the two never poll at once — they share one cursor, and both asking would mean taking turns dropping messages.",
                "Agents are no longer in Telegram's command menu, which now holds just /agents and /help. Telegram sends a command the instant you tap it, so a menu of agent names was a menu of one-tap ways to send an empty message and then wait for a reply before you could type the actual question. Typing /warren still works exactly as before — it's out of the menu, not out of the product."]),
    ("0.77.1", ["Tapping an agent in Telegram's command menu now works properly. Telegram sends a command the instant you tap it and offers no way to fill the input box instead, so a tap always arrived as a bare /name with nothing after it. Rather than scolding you for that, the bare command now opens a reply box — \"Warren is listening — what would you like to ask?\" — and whatever you type comes back as the prompt, with no need to type his name again. Typing the whole thing in one go still works exactly as before.",
                "And an agent now says it's on it the moment you ask, with how long to expect (30–90 seconds). A minute of silence reads as nothing having happened, which is the wrong impression when an agent is actually running."]),
    ("0.77.0", ["You can talk to your agents from Telegram. Send <code>/warren how exposed are we to tech?</code> and it lands in Warren's main thread — same context, same autonomy, same capabilities — and the answer comes back to the chat. It's a real thread turn, so the exchange is in the app afterwards; Telegram is a second door into the same room, not a side channel. A message with no name goes to whoever you asked last, /agents lists who's here, and agent names autocomplete because ARMADA registers them with Telegram for you.",
                "Setting it up is one screen and you don't return to it. Paste a bot token from BotFather, message the bot, press a button — ARMADA finds the chat id itself rather than making you hunt for a number. If you already run a bot elsewhere, point ARMADA at the file holding its credentials instead and it reads them when needed rather than keeping a second copy. A token ARMADA does hold lives outside every realm folder, so a realm export can't carry it off.",
                "It listens to exactly one chat: the one you linked. A Telegram bot is reachable by anyone who knows its name, so everything from anywhere else is dropped. There's an hourly ceiling too, because every message is a full agent run and agent runs spend quota — checking for messages is free, and an agent is only woken when something is actually waiting.",
                "Telegram notifications work now as well, so the column in Realm → Notifications finally does something. Connecting switches the channel on."]),
    ("0.76.5", ["An agent's dot now fades from 'unseen output' to idle while you're looking at the thread, including when the reply lands after you opened the page. That was the case still broken: a job finishing on a thread you already had open turned the dot teal and nothing cleared it until you navigated away and came back. It's now cleared on load, whenever the tab comes back to the front, on a click in the thread, and after each status poll — and a thread open in a background tab still counts as unread, because you haven't seen it.",
                "Clicking inside a thread widget on the dashboard clears it too. The widget is a frame, so the thread you're reading and the dot describing it live in separate documents; the widget now tells the page it's been read."]),
    ("0.76.4", ["Goal text now runs the full width of its card. The Modified date and the edit and delete buttons were sharing a row with the whole goal rather than just its title, so they reserved their width all the way down and every line stopped short of the right edge."]),
    ("0.76.3", ["The 'working' dot pulses smoothly again instead of flipping between two shades. The status colours were mixed against transparency, which browsers can't interpolate; they're mixed against the page colour now, which also means the dot no longer relies on a second layer to stay legible on a photograph.",
                "An agent's avatar keeps its colour while it's thinking. The in-progress turn is built in the browser and was copying the picture into a round box of its own, which threw the colour away — so the live turn looked different from every finished turn above it.",
                "Opening a thread now fades the agent's dot from 'unseen output' to idle while you watch, rather than leaving it lit until you navigate away. Marking the thread read and asking what the state is were racing each other; the dot changes immediately — you're looking at the output, after all — and reconciles with the server a moment later in case something new has started since."]),
    ("0.76.2", ["The status dot in the dashboard Register is a pixel larger — the proportional size rounded down at that avatar size and came out a shade too faint for a dense table row. On the Goals page, the coordinator's pinned chip is now grey rather than accent-tinted: it's the one owner you can't remove, and wearing the same colour as the removable ones implied otherwise."]),
    ("0.76.1", ["The colour crescent no longer gets sliced off on the Ministers cards, and it's thicker everywhere — 2px on the small avatars in goal chips, 4px at card and header size, where it was a barely-visible 1px. The clipping had the same cause as the faintness: the crescent hung outside the avatar's own box, so any container with overflow:hidden cut it. The avatar now sits inside a slightly wider box with the colour beside it, which nothing can clip.",
                "The status dot lost its ring and moved outward — its centre now sits on the avatar's edge rather than inside it. The thread widgets on the dashboard follow the same pattern: the dot that sat beside the thread title is on the avatar there too, so there's one dot per agent wherever you look, and the goals page avatars carry their colour like everywhere else."]),
    ("0.76.0", ["Agents are colour-coded differently. Avatars have no border at all now; instead the agent's colour is a filled circle sitting just behind the picture and shifted left, so a crescent of it shows down the side — 1px on the small inline avatars, up to 3px on the Ministers cards. It's the same amount of colour everywhere, and it stops the avatar from looking like a button.",
                "The activity dot moved onto the avatar's lower-right corner, the way chat apps do it, and left everywhere else it used to appear — beside the name on cards, in the agent header, in the dashboard roster. One dot, and it's attached to the thing it describes. It wears a ring in the page colour so it stays legible on a dark photograph."]),
    ("0.75.1", ["Every 'inherit' dropdown now names what you'd actually get — 'inherit realm default (high)', 'inherit realm default (Claude Opus 5)' — rather than leaving you to open Realm settings to find out. Model, Effort and Verbosity read the same way on the agent Configure page and the Appoint form, from one shared definition, so they can't drift apart again."]),
    ("0.75.0", ["Agents have a verbosity setting: Terse (the answer and nothing else), Brief (result first, then only what you need to act on it), Standard (result, the reasoning that matters, and what was ruled out) and Detailed (full reasoning, alternatives and caveats). Set a default for the realm in Settings → Realm, and override it per agent on its Configure page — so Warren can be terse and Aristotle explanatory, which is characterisation as much as configuration. Existing realms keep behaving as they did; Standard is the default.",
                "Two things hold at every level, because \"be brief\" is otherwise heard as \"do less\": it governs how much an agent writes, never how much it checks — the same work happens regardless — and failures, warnings, risks, anything needing your approval, and the exact text of an error are never abbreviated. Those are the moments brevity costs the most.",
                "The realm-icon tiles now fit on one line with the current icon and Upload: tighter spacing, and the Settings page is a little wider to make room."]),
    ("0.74.1", ["The realm icon picker is one line now — current icon, Upload and the whole set of tiles together, instead of the tiles taking a second row of mostly empty space. The realm's current icon is also marked on load rather than only after you click one, so the page no longer opens showing no selection at all; an uploaded image marks no tile, since it isn't one of them.",
                "'+ New realm' moved up beside the Settings heading. Creating a realm isn't a setting of the realm you're in, and sitting inside the Realm section it read like one."]),
    ("0.74.0", ["Timezone moved from User settings to Realm settings. It's what the scheduler runs a realm's jobs against, so keeping it on your profile meant every realm on this machine had to share one — now a realm you keep for work abroad can differ from the one you keep at home. It was already stored per realm; only the form filed it under you. A timezone saved the old way is still read, and it now appears under Realm rather than Owner in the memory every agent loads.",
                "User settings gained an 'About you' box: anything you want every agent to know — how you work, what you care about, how to talk to you, constraints to respect. It goes into that same memory verbatim, as your words rather than another generated field, which is also why the form says plainly that every agent reads it.",
                "'Nobody' is gone from 'Agents accept tasks from'. It said exactly what the on/off switch above it says, and two controls for one decision is how you end up with a switch reading 'on' while nothing works. Realms that already had it set keep working and now show the switch as off, which is what they meant."]),
    ("0.73.1", ["Settings → Realm now has the agent-to-agent section the per-agent page was already pointing at. It carries the realm-wide switch — off stops delegation for every agent, whatever their own setting says — plus the default inbox reading cadence and the default for who may assign an agent work. Those are the values an agent inherits when its own fields are left on 'inherit realm default'; until now they existed but could only be changed by editing realm.json.",
                "Agent colour moved above Autonomy on both the Configure page and the Appoint form, so the cosmetic fields — name, role, profile, colour — sit together and the behavioural ones follow."]),
    ("0.73.0", ["An agent's Configure page gained an 'Agent-to-agent communication' switch, on by default, with Inbox reading and Accepts tasks from beneath it — they grey out together when it's off, keeping their values so switching back on restores what you chose rather than resetting it. Off means the agent is out of the delegation network in both directions: nothing can be queued for it and it can't hand work out either, enforced when a task is picked up as well as when it's sent, since agents can write inbox files directly.",
                "Fixed the misaligned fields on that page. Model and Effort were landing in different rows because one grid cell carried a long helper paragraph and a bare filler cell was being used to force a row break. The inbox settings now have their own section below the soul, mission and tenets fields, which removes the cause rather than nudging the symptom. Advanced moved to the end of the page, where advanced sections belong, and reads as a real section heading instead of the small grey label it was — it had been easy to miss, wedged between two groups of fields."]),
    ("0.72.1", ["Memory cards now expand wherever you click them rather than only on the chevron, on both the realm and agent memory pages. The chevron itself moved under the card's scope icon so the two share one narrow gutter instead of costing a column each, and the left padding came in with it — every memory's text now starts noticeably further left. Editing, deleting and refreshing still work as clicks on their own, and a click that finishes selecting text no longer collapses what you were reading."]),
    ("0.72.0", ["System jobs now use the same layout as your agents' jobs. They were a separate list of cards with their own rules; they're now the same sortable table, with the same search, the same status and cadence filters, and the same list/calendar switch — plus the cost pill and the on/off switch in the row, where they belong. The first filter is the one deliberate difference: system jobs all have the same owner, so it filters by cost instead. The system calendar shows the last recorded run and the upcoming due times and leaves earlier days blank, because a system job keeps only its most recent run and guessing the rest would be inventing history; jobs that run more often than hourly aren't plotted at all.",
                "A new weekly system job re-checks your machine specs and OS version and rebuilds the 'Environment, realm and owner context' memory that every agent reads, so a RAM upgrade or an OS update stops being something you have to notice yourself. It only restates what it can read from your settings, agents and goals — your own memories and owner details are untouched, facts it can't re-probe are carried forward rather than dropped, and the previous version is kept."]),
    ("0.71.0", ["Backspace now goes back a section, the way it used to in older browsers. It deliberately does nothing while you're typing — in any field, the chat composer, or with text selected — while a dialog is open, or when combined with another key, so it can't swallow something you were writing. If there's any doubt about where the keystroke was meant to go, Backspace stays Backspace."]),
    ("0.70.1", ["The artifact headings in a thread's side panel now use a link mark rather than a dropdown chevron, which read as 'this expands' when it actually navigates."]),
    ("0.70.0", ["The 'Input artifacts' and 'Output artifacts' headings in a thread's side panel are now links. Clicking one opens the Artefacts page already filtered to that agent and that type, so going from 'what did this thread produce' to 'show me everything this agent has produced' is a single click rather than a page change followed by reapplying two filters by hand. The Artefacts page reads those filters from the address, so the links can be bookmarked or shared too."]),
    ("0.69.4", ["Fixed the 'Remove section?' dialog showing “[object Object]” instead of the question. A second confirm dialog had been added with a different call signature, and whichever loaded last won — leaving the other's callers with an unreadable prompt on a destructive action. There is now exactly one dialog in the app, accepting both call styles, and no page carries a private copy. While fixing it: the remaining 33 browser alert() pop-ups across the app were replaced with the same app-native dialog, so nothing falls back to the browser's any more."]),
    ("0.69.3", ["Replies now sit indented directly beneath the message they answer, so it's obvious which answer belongs to which request instead of having to match them by time. A reply whose original isn't on screen — filtered out, deleted, or older than the section — still shows on its own rather than disappearing."]),
    ("0.69.2", ["Fixed successful work being reported as failed. After a run finished, ARMADA printed a separator line made of box-drawing characters — and on a Windows console that can't encode them, that print raised an error which escaped the run. The agent's work was already done and saved, but the task was recorded as a failure, the agent who asked was told it failed, and a failure notification fired. Diagnostics can no longer break the work they describe: every line the runner prints is now guarded, and the console is set to UTF-8 at startup so the output stays readable rather than merely harmless."]),
    ("0.69.1", ["Expanding an inbox message now shows the instruction in full, verbatim. A message written as one long line counted as having nothing more to show, so its title was elided with an ellipsis that led nowhere — the full text was unreachable. Context and outcome are no longer clipped either. Mark-unread uses a clearer envelope icon, the expand arrow lines up with the message text rather than the line above it, message cards are a little narrower, and every pill in the app is 2px shorter."]),
    ("0.69.0", ["Inbox messages now show just their first line and expand for the rest, so a task with long instructions no longer buries the list. Messages that have been dealt with go grey while keeping their coloured status pill, so a failure still stands out among finished work. New messages gained a 'Process now' button that makes the agent act immediately instead of waiting for its next inbox run — it skips the wait but keeps every safeguard. 'Waiting' is now 'Pending', 'Handled in the last 24 hours' is 'Processed in the last 24h', the New messages heading carries a count, and an agent's own Inbox tab drops the recipient filter (every message there is already theirs) and shows its waiting count on the tab. Delete now asks with ARMADA's own dialog rather than the browser's — that dialog is shared across the app, so nothing else falls back to the browser's either."]),
    ("0.68.0", ["The Inbox gained filters — by sender, recipient and status — plus a search box inside the message archive, which now always appears rather than only once it has something in it. Each agent also has its own Inbox tab showing what it's been asked to do and what it has asked of others; it's the same view scoped to that agent, so the two can't drift apart. (The old agent Inbox tab read loose markdown files from an earlier design and would have been permanently empty now that messages are structured.) An agent's Configure tab now sets how soon it acts on a task — every minute, hourly, daily, or never — and who may assign it work, both inheriting the realm default when left blank."]),
    ("0.67.0", ["Added an Inbox page showing the tasks your agents have handed each other. New messages waiting to be picked up sit at the top, with everything handled in the last 24 hours below, and older exchanges folded into a Message archive so the page stays about what's live. Each message can be marked unread — putting it back in the waiting pile to be run again on the next pass, with its previous outcome cleared — or deleted outright. The Inbox tab carries a badge when tasks are waiting, since work agents assign each other is easy to miss when nobody asked for it."]),
    ("0.66.0", ["Agents can now hand tasks to each other. Ask Galen to get Steve to add a product to the daily price check, and it lands in Steve's inbox — he acts on it with his own context, in his own dedicated inbox thread, and the answer comes back to Galen. Checking an inbox is free (a file listing, no tokens), so an agent is only woken when something is actually waiting; a cadence of 'every minute' means 'act within a minute of being asked', not 'wake up 1,440 times a day'. Delegation chains stop after three hops, identical asks collapse, each agent has an hourly ceiling, and a task is claimed before it runs so a restart can't replay it. Delegated work is no more privileged than an agent's own: anything that changes the realm still needs your approval. Each agent can refuse delegated work or accept it only from the coordinator, and there's a realm-wide switch to turn the whole thing off."]),
    ("0.65.2", ["Fixed the bell's unread marker, which was showing two indicators stacked in the same corner — the older count badge and the new dot overlapping into a blob. There's now just the dot, with the exact count in the panel header where you'd look for it anyway, and on the bell's tooltip. 'Manage this realm' also moved inside Advanced rather than sitting below it, so exporting, archiving and deleting a realm are all behind a deliberate expand."]),
    ("0.65.1", ["The bell now shows a dot whenever anything is unread, and gives one short shake the moment something arrives — including a test notification, which reaches the bell straight away rather than on its next poll. (The shake respects your system's reduce-motion setting.) 'AI provider' became a multi-select in readiness for running a realm on more than one engine, with OpenAI Codex listed and marked 'soon'; the setting is stored as a list from the start, so adding an engine later won't reshape anyone's saved settings. 'Manage this realm' moved below Advanced, and the test buttons are now labelled 'Send a test notification'."]),
    ("0.65.0", ["Realm settings reorganised and given a lifecycle. The realm picker and its icon now share the top row, and Advanced has moved to the bottom where it belongs. A new 'Manage this realm' section adds three things, ordered from harmless to irreversible: Export writes a .zip of every file in the realm (for moving to another computer, or as a backup before a big change); Archive removes the realm from ARMADA's list without touching a single file, so the folder stays put and can be added back; and Delete removes the folder, going to the Recycle Bin on Windows and asking you to type the folder's name first. You can't delete the realm you're currently using. Also: 'Send a test' is now one button per channel rather than desktop-only, and the sign-out notification is worded 'Engine sign-in required' so it still reads correctly once more than one engine is supported."]),
    ("0.64.0", ["Notification settings now let you choose what reaches you and where. Settings → App lists the three delivery channels — in-app (the bell), desktop, and Telegram (coming shortly) — each switchable for this computer. Settings → Realm replaces the old list of checkboxes with a grid: one row per kind of event, one column per channel, so 'tell me in the app but don't interrupt me' and 'wake me on Telegram for this one only' are both things you can say. Events are grouped into your agents' work and ARMADA's own upkeep, column headings tick or clear a whole column, and a channel switched off on this computer is shown greyed with the reason. Settings saved before this update are carried forward rather than reset."]),
    ("0.63.1", ["Fixed the on/off switch on system jobs, which was invisible rather than missing — the markup left out the element the switch is actually drawn on, and the checkbox behind it is deliberately transparent, so nothing appeared. Each job now has a working toggle that reverts itself and says why if the change can't be saved. Notification history is also kept for a week rather than a month (they're stale within hours, so a month was just clutter), and the pruning job now runs daily instead of weekly."]),
    ("0.63.0", ["Jobs now has User and System tabs. System jobs are the recurring work ARMADA does to keep itself current — refreshing the model catalogue so new models appear and retired ones are marked, checking capabilities for updates, and pruning old history. They ship inside the app and can't be edited or deleted, but each can be switched off or run on demand, and every one states plainly whether it's free or spends your Claude quota. Each row shows when it last ran, how it went, and when it's next due, and a failure lands in the bell instead of disappearing. This also fixes the model catalogue refreshing on every single app start (and never at all if the app stayed closed) — it's now on a daily schedule, with startup only nudging it when it's genuinely due."]),
    ("0.62.0", ["Notifications are much quieter. 'A job starts' is now off by default — in a realm of any size it was most of the traffic and never needed acting on, while the finish (or the failure) is the part that matters. Repeated notifications also collapse: eight 'Warren finished a task' entries in a row become one row marked ×8, so a failure or an approval can't be pushed off the bottom of the list by routine chatter. And unticking a kind in Settings now skips it everywhere, the bell included — previously it only silenced the desktop, which meant the list kept filling up regardless. Switching desktop notifications off as a whole still keeps the history in the bell."]),
    ("0.61.2", ["Notification rows dropped the '→ open' label — a linked row now simply highlights as you hover it. Recoloured the markers so the colour carries the meaning: a finished task is the theme's blue (the app reporting what it did), an available update is a softer green (an offer, not a demand), while red still means something broke and amber still means something needs your decision."]),
    ("0.61.1", ["Notifications now take you where the thing happened. Job notifications open the agent's thread (where the output — or the error — landed), approvals open the approvals inbox, and capability updates open the Capabilities page. Opening the bell clears the unread count while keeping the highlight on what's new, so you can still see at a glance what arrived since you last looked."]),
    ("0.61.0", ["The bell in the top bar is now a real notification centre. It opens a panel in place — no more losing your page to go and look — listing everything ARMADA has announced, newest first, with a count of what's new on the bell itself. It's the archive behind the Windows notifications: jobs starting, finishing and failing, and things needing your approval all appear in both. Some kinds live here only, because they're worth knowing but not worth interrupting you for — a capability update being available is the first of those. Turning desktop notifications off now quiets the desktop without losing the history."]),
    ("0.60.0", ["You can now sign back in to Claude from inside ARMADA. When the Claude session lapses — which stops every agent run, not just usage reporting — a banner appears under the navigation on every page with a 'Sign in to Claude' button. It opens Claude Code's own sign-in in its own window; you complete it in your browser, and the banner clears itself as soon as ARMADA sees you're back. ARMADA never sees or stores your credentials: it starts the official flow and then simply asks whether it worked."]),
    ("0.59.2", ["The Claude usage bars in the Overview header no longer vanish without explanation. They could only ever explain themselves for one specific cause (an expired token); every other cause — including a signed-out Claude Code — rendered as nothing at all, so a real problem looked like a broken feature. Each cause now has its own plain-English line, written server-side so it's covered by tests, and an unrecognised cause still says something rather than nothing."]),
    ("0.59.1", ["Fixed the Artefacts row actions, which couldn't work at all: the file path was written into the button's inline JavaScript, where a Windows path is mangled beyond recognition (the backslash in '\\finance' becomes a form-feed character, others silently vanish), so the server was handed a path that didn't exist. Go-to-file and Delete now pass the path as data, not code. Delete also asks with ARMADA's own dialog rather than the browser's, and errors appear as a toast instead of a browser alert."]),
    ("0.59.0", ["Artefacts: clicking a row now opens the file in whatever app owns it, instead of just showing it in its folder. Input and output rows carry their own icons and the type is plain text rather than a pill, and each row gained Go-to-file and Delete actions on the right (delete asks first, removes the file from disk, and leaves the thread's record of it intact). One deliberate exception: files that can run code — .exe, .bat, .ps1, .py and similar — are revealed in the folder rather than launched, since agents write these and a row click shouldn't be able to execute one."]),
    ("0.58.2", ["Fixed Update & Restart failing to come back, a regression from the 0.57.4 port fix: refusing to share the port also stopped the restarted app rebinding the port it had just released (which lingers for a couple of minutes after closing). ARMADA now keeps address reuse — so a restart can reclaim its own port — and blocks genuine second instances by asking the port whether anyone actually answers, which a just-released port doesn't. Restart also hands the port over explicitly instead of leaving it to chance."]),
    ("0.58.1", ["Settings → App now has a Notifications section with the delivery channels: Desktop notifications (on) and Telegram (a placeholder, marked 'soon', for when it's wired up). Channels are per machine; which events notify still lives under Realm → Notifications. Also: the colour-theme cards are a fixed width so the grid no longer reflows under your cursor when you pick one, and changing a theme or colour mode keeps your scroll position instead of throwing you back to the top of Settings."]),
    ("0.58.0", ["ARMADA can now tell you when something happens, with native Windows notifications: a job starts, an agent finishes a task, a job fails, or something needs your approval. Each of the four can be switched on or off separately in Settings → Realm → Notifications, with one master switch and a 'Send a test notification' button to check they're reaching your desktop. Nothing leaves your machine, and identical alerts collapse so a job retrying in a loop can't flood you. Notifying is strictly best-effort by design — it can never delay or fail the run that triggered it."]),
    ("0.57.4", ["Fixed the real reason the app window sometimes never opened: ARMADA could claim a port it didn't own. Python's HTTP server allows address reuse, which on Windows lets a second copy bind a port a first copy is already listening on — the bind succeeds, but the system keeps delivering connections to the original. ARMADA would log 'serving on :8756' while nothing usable was listening, and the window waited for a server that never answered. A duplicate now fails immediately, and starting a second copy says so plainly instead of timing out."]),
    ("0.57.3", ["The 'View contents' and 'Go to file' actions on skills are bigger and have their labels back next to the icon, so they're easier to spot and to hit."]),
    ("0.57.2", ["'View contents' and 'Go to file' are now icon buttons (hover for the label) rather than text links, on both your skills and the system ones. The System tab's explainer is wider and splits onto two lines, with the second reading 'System capabilities can't be edited or removed: they ship inside the app and update with it.'"]),
    ("0.57.1", ["Capabilities polish: expanding a card now animates every time, not just the first (re-opening a details panel doesn't replay its animation by itself, so it's restarted by hand); the trust level is now a coloured pill like the other labels; 'Where from' is now 'Origin'; every skill — yours or a system one — gained a 'Go to file' link that opens its folder with SKILL.md selected; and the System tab's description is shorter."]),
    ("0.57.0", ["Capabilities is now split into two tabs. 'User' is everything you had before — your connectors, extensions, skills and plugins. 'System' is new: the skills ARMADA itself needs to work. The first one is Capability review, which checks that each of your capabilities is filed in the right bucket and that what it claims it can touch matches what its code actually does (the kind of thing that catches a local PDF viewer quietly fetching fonts from a CDN). System skills can't be edited or removed — they ship inside the app and are versioned with it, so they improve whenever ARMADA updates — but they're listed rather than hidden, and you can read the full text of any of them, because they read your capabilities' own files."]),
    ("0.56.5", ["Made the startup banner safe to print when there's no usable console (it contains characters a non-UTF-8 stream can't encode). Note: an earlier version of this entry claimed this was why the app window failed to open — that was wrong. Python's print() is a no-op when there's no stdout, so it was never the cause; the real culprit was a port clash, fixed in 0.57.4."]),
    ("0.56.4", ["Fixed Update & Restart turning the app window into a headless server: restart re-launched ARMADA as 'serve' regardless of how it started, so the window vanished and only came back in a browser. It now relaunches in the same mode it was started in. The app window is also wider (minimum width 1400px, opening at 1440) so the Capabilities list and its legend, and the dashboard widget grid, stop wrapping. And if the window can't open at all — most often because pywebview isn't installed — ARMADA now says so in a dialog and the log instead of exiting silently with no window and no message."]),
    ("0.56.3", ["Capability scans now file MCP servers correctly by where they run: a local stdio server (one launched by a command on your machine) is classified as an Extension that runs code here, while only a genuinely remote server (http/sse transport) becomes a Connector to an outside service. Previously every discovered MCP server was mis-filed as a remote Connector."]),
    ("0.56.2", ["Version scanning and updates are now real, not mocked. A 'Check for updates' button (and the coming daily job) queries the Claude CLI for genuinely installed plugins/MCP servers and their available versions, and the Update button runs a real 'claude plugin update'. Capabilities managed by the desktop app (not the CLI) are honestly left alone rather than faked. Removed the earlier sample version data."]),
    ("0.56.1", ["Capabilities now show versions and updates: an 'Update' badge on any item with a newer version, and in the expanded view a Version line (installed vs latest), the update notes, and an Update button that applies it with an animated 'updating' spinner. (Version data is seeded as a sample for now; a background scan will populate real installed-vs-latest.)"]),
    ("0.56.0", ["Capability control is now enforced, not just cosmetic. Disabling a capability now blocks it at the tool level on every run (passed to Claude Code as --disallowedTools), so agents genuinely can't use it. And any MCP capability an agent actually uses is auto-added to your Capabilities list under its real name (used ⇒ listed), so the list stays complete as agents discover tools."]),
    ("0.55.99", ["Each capability now has a collapsible Advanced section (an expansion inside the expansion, animated) with a per-capability permission — Always allow vs Ask the owner first (agents are told to propose before using an 'ask' capability). Skills gained a 'View skill contents' link that opens the SKILL.md in a modal when the file is available locally."]),
    ("0.55.98", ["Expanding a capability now animates open (the details panel fades/slides in) to match the caret animation."]),
    ("0.55.97", ["Capabilities: each item now has an enable/disable toggle in its actions (left of delete) — a disabled capability is dimmed and is no longer offered to your agents (it's an ARMADA-side switch; it doesn't change anything in Claude). More vertical breathing room around the 'From the developer' / 'What we found' details, 'Trust' renamed to 'Trust level', and the legend now stays put (sticky) as you scroll the list."]),
    ("0.55.96", ["Expanded capability details are cleaner: the flag now uses a proper warning-triangle icon, and the 'From the developer' / 'What we found' panels drop their box and sit on the card's own background."]),
    ("0.55.95", ["Capabilities column alignment: the type-icon column is tighter and its icon top-aligns with the title; the title+by column is now a fixed width, so the Runs, Can-touch and action columns line up vertically across every item."]),
    ("0.55.94", ["Capabilities fine-tuning: Runs and Can-touch moved left (title column tightened, actions kept to the right); their icons sit 1px lower under the captions; each row is ~3px shorter; legend icons are a bit larger and vertically centred with their text; and the shell icon is now a clearer filled terminal."]),
    ("0.55.93", ["Collapsed capability rows are now laid out as aligned columns — type icon · title + 'by' line · Runs · Can touch · actions (delete, expand) — so everything lines up down the list. The 'by' pill is a touch shorter to save vertical space."]),
    ("0.55.92", ["Capability card tweak: the 'by <maker>' pill is back below the title, the Runs and Can-touch icon groups keep their little captions and sit to the right of the title (with a wide margin), and the connection status stays inline next to the name."]),
    ("0.55.91", ["Capability items are shorter again: the Runs and Can-touch icons now sit inline on the title row (to the right, next to the name and 'by' pill) instead of in a separate band below, so each is a single line. The legend is a bit wider so its descriptions don't wrap."]),
    ("0.55.90", ["Capability card layout reworked: the 'by <maker>' pill now sits below the title; the middle of each card has labelled Runs and Can-touch sections with their icons; and the icons are coloured by each ability's own risk (read-only green, outside-service/files/network/connectors amber, runs-code and shell red) — on the cards and in the legend, whose entries now bold the leading word. For connectors, the connection state is shown as a plain green check + 'Connected' next to the name (no pill), with a circled-x marking anything disconnected."]),
    ("0.55.89", ["Capability cards are now taller: the Runs and Can-touch signals show as icons in the middle of each card, tinted by the item's risk colour (a reading-glasses mark for read-only, a code mark for runs-code, a server for outside services, and file / network / shell / connector marks). The legend now uses the same icons with a plain-English line for each and is wider so descriptions fit on one line; the self-explanatory 'Created by' key was dropped."]),
    ("0.55.88", ["The 'Connected' status is now shown only where a connection actually exists — connectors and remote/sign-in plugins — instead of on every item; local skills and local tools no longer carry it. A non-connected state (e.g. Planned / needs sign-in) still shows on any type that needs attention."]),
    ("0.55.87", ["More Capabilities polish: section title + description now sit on one line with more breathing room after each section; added a Type filter (connector / extension / skill / plugin); renamed 'Made by' → 'Created by'; the legend now lists each Runs and Can-touch label on its own line with a plain-English description, and the 'not a security audit' note moved next to the Risk key (reworded to 'Based on detected abilities and/or discrepancies. Not a security audit, do your own research.'). On each card, 'Developer says' is now 'From the developer', and 'What we found in the content' shows a green check when nothing unusual was detected or a warning mark when something was flagged."]),
    ("0.55.86", ["Capabilities page polish: the maker now shows as a 'by …' pill right next to each capability's name; the item list is width-capped (~900px) with the legend moved to a sticky column on the right; the per-bucket '+ Add' links are gone (adding will be one section-wide action); agent-specific capabilities are now a plain list of items instead of icon sub-groups; and every card uses only its capability-type icon (skill / plugin / connector / extension) — the per-item custom icons were dropped."]),
    ("0.55.85", ["Capabilities page now has a legend under the filters explaining every label — the risk tiers (Trusted / Review / Caution), who made it, the runs-as pills (reads only / runs code here / outside service) and the touch chips (files / network / shell / connectors) — using the same colours as the cards."]),
    ("0.55.84", ["Capabilities page cleaned up and made filterable: dropped the per-card type label (the sections and icons already say the type) and the tier dot (the coloured left-border carries it, and a dot read too much like an agent-status light), and removed the grey holder boxes for a lighter look. Added a filter bar — search plus Owner (realm-wide or a specific agent), Source (you / Anthropic / third-party / open-source) and Risk level (Trusted / Review / Caution) — that narrows the whole list and hides now-empty sections."]),
    ("0.55.83", ["Capabilities redesigned around trust. Each connector/extension/skill/plugin now shows, at a glance, who made it (you · Anthropic · a company · open-source), whether it runs code on your machine, and what it can touch (files · network · shell · connectors), plus a colour tier (Trusted / Review / Caution). Expand any item for its provenance: where it came from (with a source link when available), whether it's a frozen local artifact or a living remote dependency, and a declared-vs-observed panel — which never claims something is 'safe', only reports what a scan would find. Every item can now be removed."]),
    ("0.55.82", ["Usage data (the Overview Tokens/API-eq KPIs, the Usage widget, and the Claude limit bars) is now briefly cached in the browser (~30s), so jumping between sections within a few seconds reuses the last fetch — the content stays put instead of re-loading and re-showing skeletons. After the short window, or on manual refresh / the periodic auto-refresh, it fetches fresh."]),
    ("0.55.81", ["Overview header KPIs are now fixed-width and show a shimmer skeleton while the live Tokens/30d and API-eq figures load (like a social feed), then settle into place — so the row never reflows or flickers as numbers arrive. Falls back to the server value if the usage fetch is slow or the Usage widget isn't on the dashboard."]),
    ("0.55.80", ["Fixed the Overview header Tokens/30d and API-eq numbers visibly jumping on every visit. The server rendered one value (a 31-day, non-epoch snapshot) and the live usage refresh then overwrote it with a different one (30-day, epoch-aware) in a different format. Both now come from one shared epoch-aware 30-day total, formatted identically, so the number is stable."]),
    ("0.55.79", ["Settings → Version now has an always-available Restart button that reloads the app with the current local code — the way to apply changes on a local build. Previously the only restart path was hidden behind Check for updates, which does nothing without a configured update channel (so it looked broken). Check for updates now says 'local build — no update channel' instead of an error when no git remote is set."]),
    ("0.55.78", ["Removed the Thinking toggle from agent config — the Effort level already controls how much the model reasons, and Claude Code has no true 'off' (the floor is minimal effort), so a separate on/off switch was redundant. Set Effort to its lowest for the fastest, cheapest runs."]),
    ("0.55.77", ["New Advanced section (collapsed) on both realm settings and agent config: a Fallback model (used if the primary is overloaded/unavailable) and a Max budget in USD per run (a hard spend ceiling). Agents inherit the realm defaults unless overridden. Both are passed through to Claude Code (--fallback-model, --max-budget-usd)."]),
    ("0.55.76", ["Deleting a thread now uses an in-app confirm dialog (no browser pop-up) with an option to also delete that thread's artifacts from disk.",
                 "An agent's Effort level now actually reaches the engine (passed to Claude Code as --effort); previously it was stored and shown but never sent."]),
    ("0.52.5", ["Internal refactor: icons now have a single source of truth. The server icon registry is emitted to the browser once (window.mcIcon), and the client scripts render from it instead of keeping their own hand-maintained SVG copies — so an icon can't drift between the two anymore. No visible change."]),
    ("0.52.4", ["Fixed the job detail page erroring for a command job whose command is stored as an argument list (e.g. the daily system-memory refresh) — it now displays the command instead of a 500."]),
    ("0.52.3", ["Internal refactor: the web server's GET/POST routing is now a declarative path→handler table instead of long if/elif chains — easier to extend and can't silently miss a route. No behaviour change."]),
    ("0.52.2", ["Refactor: the app's visual identity (name, logo, mark, About text, window/page titles, icon file) is now defined in one place — a standalone brand module — so re-skinning is a single-file edit. No visible change."]),
    ("0.52.1", ["The titlebar now shows the actual ARMADA logo (the fist emblem + ARM/ADA wordmark) from the brand file, not a stand-in."]),
    ("0.52.0", ["The app is now called ARMADA. New logo and wordmark throughout, and every mention of the old name has been replaced — window title, headers, About, and console. The colour scheme is unchanged. (Under the hood nothing moved, so all your realms, jobs, and settings carry over untouched.)"]),
    ("0.51.34", ["Memory page tidy-ups: the agent icon now sits only on each memory card (not the section heading), the note about System memory on an agent's page is down to one line, and the realm/agent memory icons have tooltips explaining what loads where."]),
    ("0.51.33", ["Memory boundaries + more UI polish. Agents are now told to write only their own memory and to leave System/realm memory to you — and ARMADA enforces it: any write an agent makes to realm memory or another agent's memory during a turn is automatically reverted (its own memory is untouched). On the UI: realm memories carry the realm's icon (bigger, and it follows whatever icon you've set), agent memories carry an AI-agent icon, memory titles are more legible, the Expand link has more breathing room, and the add-memory dialog now says what a memory loads into with tailored examples (realm: 'E.g. Handedness' / 'E.g. Owner is left-handed'). Small touch-ups to the per-agent-memory subtitle and the appointment-date alignment."]),
    ("0.51.32", ["Memory card polish. (1) System memory now reads as \"Realm memory\" with the realm icon (dropping the SYSTEM tag) to make clear it loads for all agents. (2) Every memory box is a fixed one-line height with an Expand toggle that appears only when the content is longer. (3) Each card shows \"updated by <who> on dd-mm-yy\" — owner, an agent's name, or system (the daily job) — on system and regular memories alike."]),
    ("0.51.31", ["System memory is now a real, self-maintaining thing. It's a read-only digest of the realm's basics — owner, machine environment, realm identity, the full agent roster, and every goal at a glance — regenerated deterministically from the live data and loaded into every agent's context. You don't edit it; you change the source (owner facts in Settings, goals in Goals, agents via Appoint) and it updates itself. It refreshes automatically when a goal or agent changes and once a day (which also catches environment changes like an OS update), with a manual 'Refresh now' button on the card. Every change snapshots the previous version to memory/.system-versions for debugging. Your own realm-wide notes still live as normal, editable realm memories."]),
    ("0.51.30", ["Icon polish. Tooltips now appear when you hover anywhere over an icon's area, not only when the cursor is exactly on the drawn lines — icons no longer intercept the pointer, so the surrounding button/label catches it. The appointment handshake icon on agent cards is a touch bigger to match the others."]),
    ("0.51.29", ["Goals awareness + memory clarity. (1) Every agent now carries a high-level map of ALL realm goals (titles only, its own marked \"yours\") so it sees the bigger picture — while still loading only its own goals in full. The coordinator continues to hold every goal in detail. (2) \"Core\" memory is renamed \"System\", and each agent's Memories tab now has an infobox explaining that System memory (the realm's basics) is loaded for every agent. (3) On the agent cards, the appointment date is now just a handshake icon + dd/mm/yy, to save space."]),
    ("0.51.28", ["Real memory-scoping for goals. The realm's objectives.md (the full nine-goal North Star) was being injected wholesale into every agent — so Ray saw all nine even though only four are mapped to him. Now each agent gets the objectives FRAMING (the meta-objective and guardrails) plus only the goals mapped to it; the coordinator still sees all nine. Ray's always-on context drops from ~1.7k to ~0.5k tokens on the mission line."]),
    ("0.51.27", ["Agents are out of safe mode. When an agent runs a turn that can use tools, ARMADA now loads the real MCP servers, skills and plugins — so you can work with an agent in a thread and actually exercise its capabilities (Telegram, filesystem, skills, …), not just be told they exist. Quiet, propose-only turns still run lean. Also: a new thread now appears at the TOP of the thread list (just under Main), instead of the bottom."]),
    ("0.51.26", ["Polish + an honesty fix. (1) The Artefacts filters now use the same dropdown style as the Jobs page, with a matching Clear button. (2) The touched-date filters can't be set to a future date. (3) The thread rail's goals line is now labelled \"Agent's goals\" (each agent only ever loads the goals mapped to it — Ray carries 4 of the 9, not all). (4) \"Capabilities used in this thread\" now reflects what the agent ACTUALLY invoked, tracked from its tool calls — not a keyword guess. The old version matched on generic words (it flagged Telegram because the thread said \"owner\", the PDF viewer because it said \"local\"), which was misleading. If an agent used no connector or skill for a prompt, the panel now shows nothing."]),
    ("0.51.25", ["Two things. (1) Returning to an agent's Threads tab now reopens the last thread you were reading, instead of always snapping back to Main. (2) The Artefacts page is built: a sortable table of every file across the realm — input (what you attached) and output (what agents produced) — with columns for Name, Thread owner, Thread, Type, File, Path, and Last-touched date, newest first. Search by name/path/thread, filter by owner, type, and a touched-date range, sort any column, and click a row to open the file's folder. Each agent's own Artefacts tab shows the same table scoped to that agent."]),
    ("0.51.24", ["Artifact chips polished. Clicking an output artifact now actually opens its folder — the Windows file path (with its backslashes) was being mangled inside the click handler, so nothing happened; the path is now passed safely. And every artifact chip shows a type icon based on its extension (PDF, document, spreadsheet, code, image), the same way image inputs show a thumbnail."]),
    ("0.51.23", ["Artifacts fixes. (1) Output artifacts now show up the moment a reply finishes — the right rail refreshes on its own, no page reload needed. (2) Files an agent creates with any tool are now caught, not just the Write/Edit tools: a PDF hand-built through a shell command (as Ray does when reportlab isn't installed) now appears under Output artifacts. (3) The 'working…' animation now trails the reply — it sits at the BOTTOM of the output as the agent thinks, instead of pinned above it."]),
    ("0.51.22", ["The thread's right rail now lists its artifacts. 'Capabilities in this thread' is renamed 'Capabilities used in this thread', and below it a new 'Artifacts' block splits into Input artifacts (what you attached — images open in a lightbox) and Output artifacts (files the agent wrote or edited this thread). Click an output file to open its location in File Explorer with the file selected; files the agent has since moved or deleted show greyed out. Artifacts the agent writes into your realm (e.g. D:/Work/Hand) are surfaced; internal plumbing (job proposals, thread logs, memory) is not."]),
    ("0.51.21", ["Fixed the 'to compaction' number, which was stuck at 100% and never compacted. It was measured against an arbitrary 6,000-character limit; a single long daily brief blew past it, and the turn-count guard then blocked compaction — so it sat at 100% doing nothing. The threshold is now derived from the agent model's real context window (Opus 4.8 / Haiku = 200K tokens, Sonnet 5 / Fable = 1M), the same value the compactor uses. Those big Main threads now correctly read ~4%, and compaction actually fires when a thread genuinely approaches the window."]),
    ("0.51.20", ["Threads got smarter. (1) A new chat now names itself from the TOPIC of your first prompt (a short model-written summary), not the first few words — so long prompts still get a tidy title. (2) Every prompt now hands the agent its capability list (connectors/extensions/skills/plugins) so it reviews them against your ask and reaches for the right one. (3) The right rail shows which capabilities are in play for the current thread, grouped by type under each icon. (4) The thread header shows how full the conversation is toward its next auto-compaction (e.g. '63% to compaction')."]),
    ("0.51.19", ["New chats name themselves. If you start a fresh 'New Chat' and send a prompt without renaming it, the thread is titled from the subject of that first prompt (like the Claude app) — updating the header and the thread list on the spot. You can still rename it any time; once you do, auto-naming leaves it alone."]),
    ("0.51.18", ["Add/Edit capability modal: the Cancel button now sits next to Save at the bottom (not up in the title bar), matching the other dialogs."]),
    ("0.51.17", ["The 'Add …' form under Capabilities now shows examples tailored to the category: a connector suggests something like 'Interactive Brokers', an extension 'Local filesystem (D:/Work)', a skill 'House writing style', a plugin 'Finance toolkit' — with a matching description hint and explainer for each, instead of one generic placeholder."]),
    ("0.51.16", ["Capabilities page is easier to scan: each of the four categories now sits in its own light-grey card with a one-line description under the title; the top section is labelled 'Realm-wide' (matching 'Agent-specific' below); and each agent's own tools are laid out in the same 2×2 grid, shown by icon only (no repeated titles)."]),
    ("0.51.15", ["Capability icons now match the Claude app: Connectors use a blocks glyph, Skills a script glyph, Plugins a plug glyph. Added a new capability category — Extensions — for local tools (local MCP servers that run on this machine), distinct from Connectors, which are remote/hosted integrations. Extensions carry the puzzle icon and sit next to Connectors on every Capabilities view (agent tab, realm page, register, and settings)."]),
    ("0.51.14", ["Two fixes for running agents on Windows: (1) the black 'claude' console window no longer flashes up over the app on every turn — the engine now spawns the CLI with no window; (2) fixed 'filename or extension is too long' (WinError 206) on long threads — the conversation is now sent to the CLI over stdin instead of as a command-line argument, so it can't overflow Windows' command-line length limit."]),
    ("0.51.13", ["The agent breadcrumb now shows the section you're on (e.g. The Cabinet › Ministers › Warren › Jobs), and the agent's name in the breadcrumb is now a link that takes you to their Threads."]),
    ("0.51.12", ["Clicking an attached image in a thread now opens it in a lightbox (dark overlay, centred, click anywhere or Esc to close) instead of trying to follow the image's data-link — which the desktop window couldn't open, so Windows showed a 'Get an app to open this link' popup."]),
    ("0.51.11", ["Fixed a bug where attaching an image to a message and asking the agent to read it errored out ('expected str instance, dict found') — the image-attachment handoff broke when thumbnails were added and was never repaired. Agents can read attached images again. Also polished the attachment remove (×) button: grey, slightly bigger, with a properly centred icon."]),
    ("0.51.10", ["Clicking the empty area below the last message now clears a text selection too (previously only clicks on other UI cleared it; the transcript's bottom padding was treated as 'inside a message')."]),
    ("0.51.9", ["Agents now get full visibility into their job proposals. Every proposal is recorded in a durable ledger — proposed, approved, or rejected — so an agent can tell you exactly what happened to each one, with a newest-first event trail, instead of guessing. The status snapshot also now explains that it reflects the start of the turn, so an agent that just wrote a proposal won't wrongly conclude the pipeline is broken because it isn't listed yet (it appears from the next turn)."]),
    ("0.51.8", ["Critical fix: the thread composer JavaScript had a missing closing brace (introduced two versions ago), so the whole chat script failed to parse — which silently broke everything on the thread page: Enter-to-send, the right-click menu, attachments, and streaming. Restored the brace; all thread interactions work again."]),
    ("0.51.7", ["Fixed the thread right-click Copy / Select All menu, which stopped appearing after the window was reopened with text selection enabled (the native menu was intercepting it). The menu is now bound at the document level in the capture phase, so it fires first, reliably replaces any native menu, and keeps working after a reply refreshes the transcript. Selection-clear on outside-click is now limited to left-clicks so it never interferes with right-click."]),
    ("0.51.6", ["Agents now know the real status of their job proposals: each tool-using turn gets a live, authoritative snapshot of which of its proposals are awaiting approval, which were approved (now live), and which you rejected — so they stop guessing from the conversation. The Reject confirmation is now an in-app modal matching the other dialogs (no more browser popup). The Jobs-tab pending badge updates on its own (polls every 10s, on window focus, and right after an agent proposes one) instead of only refreshing when you navigate. And a text selection in a thread now clears when you click anywhere outside the transcript."]),
    ("0.51.5", ["Threads now have a right-click menu with Copy and Select All (the pywebview window has no native one). Copy grabs your current selection; Select All selects the whole conversation. Ctrl+C and Ctrl+A work too (Ctrl+A in the transcript selects the conversation, while staying native inside the composer)."]),
    ("0.51.4", ["Agents no longer nag about 'pending' job proposals. Because approvals/rejections happen on your Jobs page (out of the agent's view), an agent had no way to know a proposal it made earlier was already rejected — so it would wrongly claim N jobs were still cluttering its folder and offer to delete them. Agents are now told to treat each proposal as fire-and-forget: propose it, say it's awaiting approval, and never count, list, or offer to clean up proposal files."]),
    ("0.51.3", ["Threads: you can now select and copy text out of messages (pywebview had text selection disabled app-wide). The green 'Done' marker now sits at the bottom of the reply and stays there until you send your next prompt, instead of flashing at the top. (Selecting text takes full effect after you next reopen the ARMADA window; a CSS fallback already enables it in the current window on reload.)"]),
    ("0.51.2", ["Fixed the live-vs-reload rendering mismatch: right after an agent replies, the just-streamed turn is now replaced with the server's canonical render — so Markdown (bold, bullets, tables) is formatted immediately and the message action icons (Copy, etc.) are correct, instead of showing raw **markdown** and a half-drawn copy icon until you navigated away and back. This was the real cause of the 'copy icon looks different' reports."]),
    ("0.51.1", ["Fix: agents can now actually create the jobs you ask them to — thread chats are now agentic (the agent can use its Write tool to draft the proposal, read files, and search while you talk to it), so asking a minister to 'set up a daily job' now writes a real proposal instead of narrating a command. Chat polish: opening a thread jumps to the newest message (bottom); the animated 'working' indicator now shows for the whole time the agent works and turns into a green ✓ 'done' marker when it finishes."]),
    ("0.51", ["Ministers can now set up their own jobs. When you ask an agent (in a thread) to schedule recurring work, it writes a job proposal instead of shelling out. Proposals appear as a highlighted 'Proposed jobs' panel on the realm Jobs page and on that agent's Jobs tab — each showing the schedule and the prompt (or command) — with Approve / Reject. Nothing runs until you approve it (proposals live in a jobs/_pending folder the scheduler never touches), and the Jobs nav shows a count badge when any are waiting. Agents may propose both agent (prompt) jobs and command jobs; the approval card shows the exact command before you enable it."]),
    ("0.50.45", ["Attachments: images attached to a prompt now show as thumbnails in the composer and in the thread history (below the prompt they were sent with); attached files show as a named chip in both places. Also swapped the last-prompt Edit icon (was a square-with-pen, easily mistaken for the Copy icon) for a clean pencil."]),
    ("0.50.44", ["Fixed long unbroken strings (file paths, URLs) overflowing a thread message horizontally — they now wrap even with no spaces, in both the Threads section and the dashboard thread widget."]),
    ("0.50.43", ["Thread messages can now show the minister's full working trail like the Claude app — the interleaved short notes and tool-activity chips (e.g. 'Ran 3 commands', 'Edited a file') and any thought-process, not just the final answer. Re-pulled the four Cowork ministry threads (Warren, Steve, Marcus, Galen) with their activity trail; the activity is display-only (the final answer is what feeds context)."]),
    ("0.50.42", ["Thread messages now render Markdown — bold, italics, headings, bullet and numbered lists, tables, inline code and code blocks, and links — so a minister's reply reads the same as in the Claude app (structure and emphasis; font aside). Content is escaped first, so only safe formatting is rendered. Copy still yields the raw Markdown."]),
    ("0.50.41", ["Thread management: a thread's ⋮ menu now has Archive and Delete (Delete asks for confirmation and is permanent; neither is offered for the main thread). Archived threads drop out of the left list; a new 'Archived' button at the bottom of the thread panel opens a list of them (title + archived date) where each can be Revived or Deleted."]),
    ("0.50.40", ["The realm Jobs section gained a search box (between the list/calendar icons and the filters). It filters the list and the calendar together, alongside the owner/status/cadence filters, and the Clear button resets it too."]),
    ("0.50.39", ["An agent's own Jobs tab now has the same Status and Cadence filters as the realm Jobs page (alongside the existing search), so you can narrow a single agent's jobs by last-run status or cadence."]),
    ("0.50.38", ["Jobs filters (owner · last-run/status · cadence) now also filter the calendar view, not just the list. The Jobs page remembers your last view (list or calendar) and reopens in it — list stays the default until you pick calendar. Filter dropdowns are now fixed-width, so they no longer jump around when you pick a shorter option."]),
    ("0.50.37", ["Job calendar (widget and Jobs page): clicking '+N more' in the month view now opens that day in the Day view, so you can see all of its jobs."]),
    ("0.50.36", ["Jobs view polish: the list/calendar selector moved into the filter row (borderless icons, before the filters); switching to Calendar now just swaps the table — the filters and legend stay put above it. The Jobs-page calendar drops its own bottom legend (the status legend already sits above it), and the Overview calendar widget's legend no longer lists 'Not scheduled' (a per-job state that doesn't apply to a per-day calendar)."]),
    ("0.50.35", ["The Overview Job-calendar now uses the same colour language and legend as the Jobs section (teal Success, hollow-teal Scheduled, light-green Running, amber Warning, red Failed, grey Missed). The Jobs page gained a list/calendar toggle — the calendar view is the very same widget. Also made the 'Not scheduled' legend swatch border-less to match the strip."]),
    ("0.50.34", ["Jobs health tweaks: dropped the weekend border (cleaner); 'Scheduled' is now a hollow teal square (outline only); added a 'Running' state (light green) for jobs executing right now — shown in the strip, the Last-run column, the legend and the status filter. The legend now includes 'Not scheduled', and the status filter says 'Missed' instead of 'Never run'."]),
    ("0.50.33", ["Jobs 7-day health is now schedule-aware: a day the job wasn't due reads 'Not scheduled' (faint) instead of a false 'Missed', and a job due later today shows a new blue 'Scheduled' state rather than looking missed — which also clears the Last-run/health mismatch. Added a 'Status as of DDD HH:MM' stamp (realm time) and a Refresh button that recomputes every job's state. Legend updated (Success · Scheduled · Warning · Failed · Missed)."]),
    ("0.50.32", ["Jobs filters now use the same dropdown style as the realm switcher, with a colour swatch next to each status option. Any open dropdown (and the realm switcher) now closes when you click anywhere outside it. In the 7-day health strip, weekends are marked with a thin border instead of a lighter shade — so a weekend colour now matches the legend exactly (a weekend failure is properly red, just outlined)."]),
    ("0.50.31", ["Jobs polish: the filter dropdowns now look like proper selects (surface fill, chevron, hover + focus ring); added a colour legend for last-run status (Success / Warning / Failed / Missed); the 7-day health column header now shows the day letters aligned over each square, and hovering a square tells you the day and its status (e.g. 'Monday 08 Sep · Success')."]),
    ("0.50.30", ["Jobs section can now be filtered at the top by owner, last-run status (Success / Warning / Failed / Never run) and cadence (Daily / Weekly / Monthly / Quarterly / Other), with a live 'shown of total' count and a Clear button. Filtering works alongside column sorting."]),
    ("0.50.29", ["Threads can now show inline event cards alongside messages — e.g. 'Created scheduled task …' (with its cadence and a link) and a live 'Compacting our conversation …' progress bar. Events are stored in the thread but kept out of the model's context and preserved across compaction. See the coordinator's 'events-demo' thread for a preview."]),
    ("0.50.28", ["Job calendar opens on the Week view by default. Modals now close only on a clean click outside — selecting text inside a field and releasing over the modal border no longer dismisses it. Fixed the double-border look when renaming a thread from the chat header (now matches the left panel)."]),
    ("0.50.27", ["Hardening pass (pre-wizard): CSRF/Origin guard on all POSTs; server logging to ~/.matcap/logs with tracebacks instead of silent excepts; a cross-process write lock so the always-on scheduler and the app can't lose each other's edits (thread appends, realm.json); saving User settings now merges into the core memory instead of overwriting your manual edits; version is single-sourced; added docs/SCHEMA.md (the realm on-disk contract)"]),
    ("0.50.26", ["Birthdate picker limited to 1930–2020"]),
    ("0.50.25", ["User settings polish: timezone is now a dropdown ordered west→east with 'System (your OS timezone)' first, showing the live app time ('Job schedules will be based on this time'); all fields share one height; birthdate can't be after 2020; gender defaults to 'Prefer not to say'"]),
    ("0.50.24", ["New User settings tab (name, avatar, timezone, gender, birthdate) — the source of truth, editable here and saved into the realm + the agents' core memory. A user avatar (upload or pick from the set) shows in threads instead of 'You'. Appoint form labels now match Config (Soul before Role and Mission). Textarea scrollbars match the widget style. App window min width raised to 1200px."]),
    ("0.50.23", ["Agent cards show a memory count (brain) next to goals. Config: Soul moved above Role and Mission (renamed from Mandate), tenets labelled 'specific rules'. Names ending in s take a bare apostrophe (Marcus’ memory). Double-click a thread name — in the list or the chat header — to rename it in place."]),
    ("0.50.22", ["Fixed editing a memory: it no longer grabs the CORE badge into the title or drops the 'kind: core' marker — the edit form reads the clean title and the save preserves existing frontmatter"]),
    ("0.50.21", ["Threads 'Loaded context' now breaks the prompt into Mission/soul/tenets · Goals · Realm memory · Agent memory · Thread context — measured on the exact section text assemble_core injects, so the bar can't drift from what actually goes to the model"]),
    ("0.50.20", ["Agents get a Goals tab (2nd, after Threads) listing their goals — add one there and it's auto-owned by that agent. Config: removed the Claude model icon and the Capabilities block. Threads: center header now matches the side pane (capitalised/renamed) and the thread list is drag-resizable. Add-goal/add-memory modals say 'for [Agent]' on an agent's page. New realms seed a marked 'core' memory (owner + environment) that loads into every agent."]),
    ("0.50.19", ["Memory & Memories pages match Goals: '+ Add memory' button opens the add form in a modal; the page is just the search + list (no inline form)"]),
    ("0.50.18", ["Minister cards now show a goals count (target icon, first in the footer row) — how many goals that agent owns; the coordinator counts all goals"]),
    ("0.50.17", ["Role labels adapt to realm type (Prime Minister/Minister for a state, CEO/Executive for a company, Captain/Mate for a crew); 'Hand' is now private to the owner's Cabinet and never shown to other users; goal cards always show an ETA row (‘not set’ when blank)"]),
    ("0.50.16", ["Goals polish: add-goal is now a modal (+ Add goal button); a right-hand Agents roster you drag onto a goal to set an owner (coordinator pinned); cards say 'Owners:'; each goal shows its ETA; a past ETA shows the goal as At risk; status field aligned to the other inputs"]),
    ("0.50.15", ["New Goals section (after Ministers): add objectives one by one with status + target date, and map agents to each from an on-page roster (the coordinator is pinned to every goal). Mapped goals load into every thread for those agents' context."]),
    ("0.50.14", ["Memory: the 'Modified dd-mm-yy' stamp now sits on each memory card (by its title), showing when that memory itself was last changed — realm and per-agent"]),
    ("0.50.13", ["Register Appoint now opens the form in a modal (no page redirect); Memory & Memories pages show a 'Modified dd-mm-yy' stamp by the title; agent sections reordered to Threads · Jobs · Inbox · Memories · Artefacts · Capabilities · Overview; new-thread icon swapped to ri/chat-new-line (alt 'New thread')"]),
    ("0.50.12", ["Composer fixes: single-row layout (prompt sits beside the +), truly one line by default, ↵ icon now appears on typing (fixed a script-init bug), smooth grow animation"]),
    ("0.50.11", ["Composer redesigned (Claude-style): no Send button/hint, borderless plus, return-arrow icon appears as you type, single-line box that grows smoothly"]),
    ("0.50.10", ["Thread widget: composer/fade no longer covers the scrollbar — it stays fully visible to the bottom (Claude-style)"]),
    ("0.50.9", ["Thread chat now scrolls full-height with the composer floating over a fade-out (Claude-style); main scrollbar 2px narrower"]),
    ("0.50.8", ["Thread conversations now show the agent's real avatar (uploaded image) on its replies, not just the default bust"]),
    ("0.50.7", ["Thread-widget (chat transcript) scrollbar now matches the other widgets - subtle, hover-only"]),
    ("0.50.6", ["Fix: main app scrollbar now actually renders chunkier with side padding (WebView2 was honouring the standard thin bar and ignoring the custom styling; dropped scrollbar-width so the webkit styling applies)"]),
    ("0.50.5", ["Main scrollbar has 5px clear padding on each side"]),
    ("0.50.4", ["Main app scrollbar now sits at the far-right window edge (separated from the widget bars) and is chunkier"]),
    ("0.50.3", ["Main app scrollbar is a bit chunkier (distinct from the widget ones) and sits closer to the right edge"]),
    ("0.50.2", ["App window title is just “ARMADA”; app-section scrollbars restyled to match the widgets (hover-only, subtle, reserved gutter so they never overlap content)"]),
    ("0.50.1", ["Removed the in-app title strip (the OS window title already shows it); the app window/taskbar now uses the ARMADA mark as its icon"]),
    ("0.50", ["ARMADA now opens as a native desktop window (matcap app) via pywebview — the same cockpit, in its own window instead of a browser tab"]),
    ("0.49.7", ["The widget width selector chip now uses the same #eee as the header, so it blends in"]),
    ("0.49.6", ["Widget header bars now have a light grey (#eee) background; restored the job-calendar toolbar divider (lighter grey) to match Usage"]),
    ("0.49.5", ["Usage toolbar divider restored, in a lighter grey"]),
    ("0.49.4", ["Register Appoint button now opens the appoint flow; Job calendar month/week/day + ‹Today› controls restyled to match Usage (grey-selected pills, subtle nav); removed the Usage toolbar's divider line"]),
    ("0.49.3", ["Usage toolbar polish: Line/Graph are now icons; interval and Agents/Models controls are plain text with a grey selected pill"]),
    ("0.49.2", ["Usage graph now fills the widget width (weekly & monthly alike) and hover tooltips on bars/segments work"]),
    ("0.49.1", ["Usage graph is taller and a fixed height for both weekly & monthly (matching x-axis font); graph now stacks each bar by agent (default) or model — toggle top-right — with per-segment hover tooltips. Resize handle no longer overlaps the scrollbar"]),
    ("0.49", ["Usage widget: Line vs Graph modes. Line has Today / 7D / YTD / 365D intervals; Graph shows a weekly (7-day) or monthly (12-month) token chart",
              "Subtle hover-only widget scrollbars (thinner, widget-toned) with room for the resize handle; Register Jobs count centered"]),
    ("0.48", ["Widgets are now height-resizable: drag the bottom-right corner to make a widget taller/shorter (great for thread widgets); others reflow around it, and the height persists"]),
    ("0.47.1", ["Register: added a Model column (model · effort) after the member name"]),
    ("0.47", ["App sections: a local mini-site (like the Daily Digest) now renders with its OWN header — edition picker, prev/next, and light/dark toggle all work in-app, served locally so no firewall gets in the way"]),
    ("0.46.1", ["Mirrored sections can inline a stylesheet, so a bare content fragment (like the Daily Digest build) renders fully styled in the app instead of raw"]),
    ("0.46", ["Mirrored sections: a published artifact (e.g. Daily Digest) keeps a local copy inside the realm and opens instantly in the app — no firewall/embedding issues — with a Refresh button and an ‘Open published’ link. Refreshes automatically from its source (newest local build, or a URL)"]),
    ("0.45.4", ["Sections that point to a website now have an ‘Open in browser’ button — so a site that refuses to embed (firewall / ‘verifying…’ challenge) is still reachable"]),
    ("0.45.3", ["Job calendar loads ~180× faster (cron projection no longer scans 1440 min/day) and caches views for 60s, so switching Month/Week/Day is instant"]),
    ("0.45.2", ["Polish: tighter widget-manager rows (checkbox aligned to title); Edit-memory Cancel now sits next to Save; the active nav tab underline is thicker and meets the divider"]),
    ("0.45.1", ["Fix: widgets no longer overlap (uniform row height with internal scroll); Job calendar caches views for 5s so switching Month/Week/Day is instant"]),
    ("0.45", ["New Job calendar widget: scheduled jobs in month / week / day views (switchable), past runs colour-coded by status (success / failed / warning / missed), hover for details, click to open the job"]),
    ("0.44.2", ["Fix: the Go-to-agent menu icon renders fully now; unread thread widgets lose the blue border (bold blue title + a status dot are enough) — and the dot is now always shown, reflecting read/unread"]),
    ("0.44.1", ["Fix: the ⋮ options icon is now visible (bigger dots), and the header avatar no longer clips at the top"]),
    ("0.44", ["Thread widget header: agent avatar next to the name, and a ⋮ menu (Go to agent · Mark unread/read · Rename · Remove) replacing the old controls; unread widgets get an accent bar, dot and title tint; Remove now confirms first"]),
    ("0.43.1", ["Fix: the drag grip was invisible and un-grabbable (leftover edit-mode CSS) — it now shows by each title and drag-to-reorder works, including across thread widgets"]),
    ("0.43", ["Dashboard widgets are now editable in place — no more Edit layout mode: drag the grip by each title to reorder, and use the subtle ‹ 25% › control in the header to resize (others wrap to fit)"]),
    ("0.42", ["Thread widget: the thread type and live message count now sit in the widget's header bar; the redundant second line inside the chat is gone"]),
    ("0.41", ["Add widget is now a widget manager: see what's on your dashboard (top) vs. available (bottom); toggle single-instance widgets (Register, Usage) with a checkbox and add thread widgets from a form"]),
    ("0.40", ["Thread widgets: add any agent's thread to the Overview as a live conversation and chat in it — same UI as the Threads tab; add as many as you like via Add widget"]),
    ("0.39", ["Usage widget now lists every agent (top-usage → least, idle ones dimmed) and every available model with its token use"]),
    ("0.38", ["New Usage widget on the Overview: overall tokens (all agents & models), broken down per agent and per model, from ARMADA's own run telemetry"]),
    ("0.37", ["Overview is now a customizable dashboard: the Register is the first widget, with an Add widget button for more to come",
              "Register shows an Autonomy column and a Status column (status dot + latest activity), and the status dot is off the avatar"]),
    ("0.36", ["The app never caches now, so UI updates always show after Update & Restart"]),
    ("0.35", ["Style updates now take effect on refresh (versioned stylesheets); the edit tooltip wraps and the info icon is clearer"]),
    ("0.34", ["Images you attach or paste are now sent to the agent to look at",
              "Edit: Save stays disabled until you change something; tooltip moved to the info icon and no longer clips"]),
    ("0.33", ["Editing a message shows a Save button with a 'restarts from here' tooltip; paste an image or file straight into the chat; the + menu is just files/photos for now"]),
    ("0.32", ["Chat polish: bigger working animation; timestamps + copy on every message; restart-from-here + edit on your messages; a Stop button; and a + menu to add files or photos",
              "Cleaner user bubbles (no border)"]),
    ("0.31", ["The model you pick per agent (or the realm default) is now used for real, mapped to a valid engine model",
              "Animated brain indicator while the agent is working"]),
    ("0.30", ["Chats now stream live: thinking and tool steps ('Running a command', 'Reading a file') appear as they happen, with details on click, then the answer"]),
    ("0.29", ["Default avatar re-centred with a little top room so the head doesn't touch the edge",
              "Appointed date set to 11px; coordinator avatar matches the others (single border, accent colour)"]),
    ("0.28", ["Default avatar nudged to sit centred in the circle",
              "Appointed date moved to the card footer; more of the profile shown; extra spacing under the model"]),
    ("0.27", ["Agent cards are a fixed height with the capability icons pinned to the bottom",
              "Default avatar fills the circle cleanly; 3P/inherited labels reuse the model-pill style"]),
    ("0.26", ["Threads: drag to reorder, a 3-dots menu (Pin/Unpin, Mark read/unread, Rename)",
              "The main thread always stays on top and can't be unpinned",
              "New-chat button uses a clearer compose icon; default agent avatar refreshed"]),
    ("0.25", ["Capabilities now order Connectors → Plugins → Skills everywhere",
              "Agent cards show active connector/plugin/skill counts at a glance",
              "Threads is the first tab and the default view for an agent; Overview moved to the end",
              "New-thread starts a fresh chat instantly (no naming prompt), like the Claude app",
              "Bigger chat composer sized like the Claude app"]),
    ("0.24", ["Connector icon aligns with the name; scope/description sit neatly below",
              "Add connector opens an explainer (connectors are enabled in Claude, then refreshed in)",
              "Refresh icon by Connectors pulls the MCP servers Claude Code can see"]),
    ("0.23", ["Connectors now show a description line (seeded for the cabinet's real tools)",
              "The inherited / 3P / Custom labels share one uniform pill style",
              "Clearer sort icons on job tables; model pill on minister cards matches the agent header",
              "Click a memory in the overview to jump to it (highlighted) in Memories; brain icon in the per-agent list"]),
    ("0.22", ["Capabilities are tagged 3P (third-party) or Custom; delete any, edit your custom ones, add new",
              "Add-section is now a modal opened from the top-menu +",
              "Clicking a job from a list opens that job in the Jobs tab",
              "\"Editing\" button spacing fixed to match the selected style"]),
    ("0.21", ["Skills renamed to Capabilities; agent-specific tools split into Connectors / Skills / Plugins",
              "Manage button explains that connectors, skills and plugins are added in Claude first",
              "Model shown on agent cards; Configure lists all Claude models (incl. Fable) with the Claude mark",
              "Start a new thread from the Threads tab",
              "Square +/edit section buttons; edit button now exits edit mode cleanly",
              "IBKR shown with its brand-coloured mark; avatars re-centred"]),
    ("0.20", ["Autonomy icon shown on agent cards and headers; role sits below the name",
              "Agent Jobs tab and Memory both gained a search box (with clear); memory Edit/Delete are icons",
              "Realm Skills page lists agent-specific tools below the realm-wide ones",
              "Sharper avatars (re-cut at 512px, shoulders to the circle edge); remove-avatar option",
              "'-' at a line start becomes a bullet in text fields, like the Claude composer",
              "Section edit mode persists on the edit page; delete is an in-app modal",
              "Settings: stay on your tab when switching mode/realm; spacing & encoding fixes"]),
    ("0.19", ["Per-agent autonomy: Manually approve / Automatically approve / Skip all approvals",
              "Realm-wide + per-agent Skills, Plugins & Connectors (seeded from the live cabinet)",
              "Agent header re-laid out; model & effort and a gear beside the name",
              "Jobs table shows a weekday 7-day health strip; cron help on the job editor",
              "Memory edit & delete in modals, plus a search box",
              "App settings: check-for-updates, changelog, per-provider engine, colour mode & theme"]),
    ("0.18", ["Settings split into Realm and App tabs; app version shown",
              "Realm dropdown polish; avatar 'pick from set' modal; memory add/edit/delete"]),
    ("0.14", ["UI feature-complete: realm pages, job editor, create flows, multi-realm switcher"]),
]


def _changelog_modal(ver: str) -> str:
    blocks = ""
    for v, items in _CHANGELOG:
        cur = ' <span style="font-size:10.5px;color:var(--color-accent-2);font-weight:600">current</span>' if v == ver else ""
        lis = "".join(f'<li style="margin-bottom:3px">{E(x)}</li>' for x in items)
        blocks += (f'<div style="margin-bottom:12px"><div style="font-family:var(--font-heading);font-weight:600;font-size:14px">v{E(v)}{cur}</div>'
                   f'<ul style="margin:4px 0 0;padding-left:18px;font-size:12.5px;line-height:1.5">{lis}</ul></div>')
    return (f'<div id="mc-changelog" class="mc-modal-ov" onclick="if(event.target===this)mcChangelog(false)">'
            f'<div class="mc-modal-box" style="padding:20px;width:min(560px,92vw);max-height:80vh;overflow:auto">'
            f'<div style="display:flex;align-items:center;margin-bottom:12px"><div style="font-family:var(--font-heading);'
            f'font-weight:600;font-size:17px">Changelog</div>'
            f'<button class="btn btn-secondary" style="margin-left:auto;font-size:12px;padding:4px 10px" onclick="mcChangelog(false)">Close</button></div>'
            f'{blocks}</div></div>')
